INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('3a0b4f64-9472-4232-a870-3ae750c75174', 'among-us', 'Among Us', 'Work together to keep your ship alive — but watch out for the impostor.', 'A party game of teamwork and betrayal. Complete tasks aboard a spaceship with your crewmates, while one of you quietly sabotages everything and picks off the crew. Deduce, debate, and vote out the impostor — the ultimate social deduction game.', 'InnerSloth', 'InnerSloth', '2018-06-15', '["Party","Casual","Indie"]', '["Social Deduction","Multiplayer","Co-op","Memes","Short"]', '["Online Co-op","Local Co-op","Voice Chat","Cross-Platform Play"]', '/covers/among-us.hero.jpg', '/covers/among-us.box.jpg', 85, '$4.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch","Mobile (iOS/Android)"]', '["Online Co-op","Online PvP","Local Co-op"]', 'E10+ (Everyone 10+)', 'Unity', 'N/A', 85, 'Very Positive', '500+ million players at its 2020 peak', 0, 0, '["Best Mobile Game 2020 (The Game Awards)","Best Multiplayer 2020 nominee"]', '["It was released in 2018 but exploded in popularity in mid-2020","Congresswoman Alexandria Ocasio-Cortez played it live on Twitch to encourage voting","The words \"sus\" and \"impostor\" entered internet slang worldwide","Its crewmate design was inspired by a doodle of a jelly bean"]'),
('b5760c21-1437-4da7-a91f-192cd6aee0fd', 'animal-crossing-new-horizons', 'Animal Crossing: New Horizons', 'Escape to a peaceful island paradise you can shape as you like.', 'Build your own island getaway, meet charming animal villagers, catch bugs and fish, decorate your home, and live life at your own pace. A gentle, ever-changing world that rewards daily visits and creativity — the ultimate cozy game.', 'Nintendo EPD', 'Nintendo', '2020-03-20', '["Simulation","Adventure"]', '["Cozy","Life Sim","Crafting","Relaxing","Multiplayer"]', '["Single-player","Local Co-op","Online Co-op","Controller Support"]', '/covers/animal-crossing-new-horizons.jpg', '/covers/animal-crossing-new-horizons.jpg', 90, '$59.99', 0, '["Nintendo Switch"]', '["Single-player","Local Co-op","Online Co-op"]', 'E (Everyone)', 'In-house (Nintendo EPD)', 'Animal Crossing', 90, 'Positive (not on Steam)', '45+ million copies sold; best-selling Nintendo Switch exclusive', 60, 350, '["Best Family Game 2020 (The Game Awards)","BAFTA Game of the Year 2021"]', '["It became a cultural phenomenon during 2020''s pandemic lockdowns","Players recreated famous museums, fashion shows, and even weddings on their islands","Turnip trading (\"the Stalk Market\") became a real economic mini-game for fans","A fan-made Animal Crossing run set a world record for most Bells earned"]'),
('660a3b51-d2ac-41c7-929f-644329c9b18c', 'apex-legends', 'Apex Legends', 'A squad-based battle royale with fluid movement and unforgettable heroes.', 'Choose from a roster of legendary characters with unique abilities and fight in three-person squads across fast, fluid battle royale matches. With refined gunplay, innovative ping systems, and constant seasonal content, Apex remains a top competitive shooter.', 'Respawn Entertainment', 'Electronic Arts', '2019-02-04', '["Shooter","Action","Free to Play"]', '["Battle Royale","Multiplayer","PvP","Hero Shooter","Team-Based"]', '["Online PvP","Cross-Platform Play","Voice Chat","Controller Support","Leaderboards"]', '/covers/apex-legends.hero.jpg', '/covers/apex-legends.box.jpg', 88, 'Free', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch","Mobile (iOS/Android)"]', '["Online PvP","Squad-based (Trios, Duos)"]', 'T (Teen)', 'Source (Respawn fork)', 'Titanfall', 88, 'Mostly Positive', '130+ million players worldwide', 0, 0, '["Best Multiplayer Game 2019 (The Game Awards)","Best Ongoing Game 2020 nominee"]', '["It launched with zero marketing and hit 25 million players in one week","Its ping system revolutionized communication in shooters","Characters like Wraith and Octane became pop-culture icons","Titanfall''s wall-running movement was refined into Apex''s slide and climb system"]'),
('6bb53ce9-495e-450b-a732-169a76185c9d', 'ark-survival-evolved', 'ARK: Survival Evolved', 'Tame dinosaurs and survive a mysterious prehistoric world.', 'Wake up on a mysterious island filled with dinosaurs and other survivors. Tame and ride creatures from the T-rex to the dragon, build fortresses, craft technology, and uncover the mysteries of ARK — solo or with up to ten-player tribes.', 'Studio Wildcard', 'Studio Wildcard', '2017-08-29', '["Survival","Action","Adventure"]', '["Dinosaurs","Multiplayer","Crafting","Open World","Taming"]', '["Single-player","Online PvP","Online Co-op","Controller Support","Steam Workshop"]', '/covers/ark-survival-evolved.hero.jpg', '/covers/ark-survival-evolved.box.jpg', 76, '$9.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player","Online PvP","Online Co-op"]', 'T (Teen)', 'Unreal Engine 4', 'ARK', 76, 'Mostly Positive', '35+ million copies sold', 0, 0, '["Best Survival Game 2017 nominee (multiple outlets)"]', '["Players can tame and ride over 150 species of dinosaurs","Its lore reveals the island is actually a space station","The ARK survival of the fittest mode became an esports tournament","Vin Diesel narrated the game''s 2023 sequel, ARK 2"]'),
('dbb5a6fe-c8c1-418d-a306-b1a814015bda', 'baldur-s-gate-3', 'Baldur''s Gate 3', 'Gather your party and return to the Forgotten Realms in this epic RPG.', 'An epic narrative RPG set in the world of Dungeons & Dragons. Forge your destiny through hundreds of choices, turn-based tactical combat, and a sprawling story of up to 4-player co-op. Baldur''s Gate 3 redefines what a CRPG can be, with unforgettable characters and truly reactive storytelling.', 'Larian Studios', 'Larian Studios', '2023-08-03', '["RPG","Strategy","Adventure"]', '["Turn-Based","Story Rich","Co-op","Character Customization","Choices Matter"]', '["Single-player","Online Co-op","Local Co-op","Controller Support","Cloud Saves","Achievements"]', '/covers/baldur-s-gate-3.jpg', '/covers/baldur-s-gate-3.jpg', 96, '$59.99', 0, '["PC","PlayStation 5","Xbox Series X|S","macOS"]', '["Single-player","Online Co-op","Local Co-op (Split-screen)"]', 'M (Mature 17+)', 'Divinity 4.0', 'Baldur''s Gate', 96, 'Overwhelmingly Positive', '15+ million copies sold; a record-breaking turn-based RPG', 75, 159, '["Game of the Year 2023 (The Game Awards)","Best RPG 2023","Best Community Support 2023","BAFTA Best Game 2024"]', '["Over 170 hours of cinematic cutscenes — more than any game ever made","It was in early access for nearly 3 years, shaped by millions of player decisions","Larian''s CEO Sven Vincke bought the D&D license personally after Wizards of the Coast passed","The Dark Urge origin can be played as an evil campaign with unique scenes"]'),
('dfcc8105-c8c4-4288-9893-d3cbf4274229', 'cities-skylines', 'Cities: Skylines', 'The definitive modern city builder, with deep systems and endless creativity.', 'Design, build, and manage the metropolis of your dreams. With intricate traffic simulation, zoning, public services, and economy systems, Cities: Skylines is the deepest city builder ever made — and a relaxing creative sandbox all at once.', 'Colossal Order', 'Paradox Interactive', '2015-03-10', '["Simulation","Strategy","Indie"]', '["City Builder","Management","Relaxing","Creative","Sandbox"]', '["Single-player","Steam Workshop","Cloud Saves","Achievements"]', '/covers/cities-skylines.hero.jpg', '/covers/cities-skylines.box.jpg', 85, '$29.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'E (Everyone)', 'Unity', 'Cities', 85, 'Mostly Positive', '12+ million copies sold', 0, 0, '["Best Simulation Game 2015 (multiple outlets)"]', '["It was created as the long-awaited successor to SimCity after SimCity''s 2013 flop","Every citizen is individually simulated, with a job, home, and commute","Its traffic system is so accurate it''s used in urban planning lectures","Paradox turned it into a franchise with three major expansions and a sequel"]'),
('f5bd493b-e20d-4ba5-bb9f-b9b5b7fa53d0', 'counter-strike-2', 'Counter-Strike 2', 'The world''s premier competitive FPS, rebuilt on a new engine.', 'Counter-Strike 2 is the largest technical leap in Counter-Strike history, with new volumetric smoke, upgraded maps, and reworked lighting. The definitive tactical shooter where precision, teamwork, and a thriving competitive scene make every round count.', 'Valve', 'Valve', '2023-09-27', '["Shooter","Action","Free to Play"]', '["FPS","Competitive","Multiplayer","PvP","Team-Based"]', '["Online PvP","Cross-Platform Play","Leaderboards","Voice Chat"]', '/covers/counter-strike-2.hero.jpg', '/covers/counter-strike-2.box.jpg', 83, 'Free', 0, '["PC","PlayStation (via streaming)","Xbox (via streaming)"]', '["Online PvP"]', 'M (Mature 17+)', 'Source 2', 'Counter-Strike', 83, 'Very Positive', '1.8+ million peak concurrent players on Steam; one of the most-played PC shooters', 0, 0, '["Esports Game of the Year 2023 nominee","Longest-running competitive FPS franchise in history"]', '["Counter-Strike began as a Half-Life mod by Minh Le and Jess Cliffe in 1999","Its competitive format is still the industry''s default for 5v5 shooters","Every map was rebuilt from scratch for Source 2","The economy system — earning money each round — remains a genre innovation"]'),
('deb0d6f1-d256-4906-841d-521f99cde4b9', 'cyberpunk-2077', 'Cyberpunk 2077', 'An open-world action-adventure story set in Night City.', 'Become a cyberpunk mercenary in the megalopolis of Night City, where style and violence meet in a dystopian future. With the heart-pounding story of the Phantom Liberty expansion and the vibrant open world, Cyberpunk 2077 is a thrilling RPG of ambition, body modification, and neon-lit danger.', 'CD Projekt Red', 'CD Projekt', '2020-12-10', '["RPG","Action","Shooter"]', '["Open World","Cyberpunk","Story Rich","First-Person","Sci-fi"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/cyberpunk-2077.jpg', '/covers/cyberpunk-2077.jpg', 86, '$59.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'M (Mature 17+)', 'REDengine 4', 'Cyberpunk', 86, 'Very Positive', '30+ million copies sold; a comeback story after a rocky launch', 103, 170, '["Best RPG 2020 (multiple outlets)","Golden Joystick Most Wanted 2020 (pre-release)"]', '["Keanu Reeves'' character Johnny Silverhand was written specifically for him","Its controversial 2020 launch led to class-action lawsuits and a PlayStation Store removal","The Phantom Liberty expansion, released in 2023, was widely praised as a redemption arc","Its Night City map was built with real city-planning software"]'),
('1e540e0b-998f-40c9-a345-ddd40254293f', 'dark-souls-iii', 'Dark Souls III', 'The fires are fading in the brutal finale of the legendary Souls trilogy.', 'Journey to a dying world of crumbling kingdoms and monstrous lords of cinder. With ferociously demanding combat, intricate level design, and a haunting atmosphere, Dark Souls III is FromSoftware''s acclaimed trilogy-capper — a challenge like nothing else.', 'FromSoftware', 'Bandai Namco Entertainment', '2016-04-12', '["Action","RPG"]', '["Souls-like","Difficult","Dark Fantasy","Atmospheric","Single-player"]', '["Single-player","Online PvP","Online Co-op","Controller Support","Achievements"]', '/covers/dark-souls-iii.hero.jpg', '/covers/dark-souls-iii.box.jpg', 89, '$39.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player","Online PvP","Online Co-op"]', 'M (Mature 17+)', 'In-house (FromSoftware)', 'Souls', 89, 'Very Positive', '10+ million copies sold', 32, 60, '["Golden Joystick Ultimate Game of the Year 2016 nominee"]', '["Its final DLC, The Ringed City, closes the entire Dark Souls saga","The soul level 1 run — beating the game without leveling — remains a legendary challenge","Firelink Shrine''s music is an orchestral variation of the series'' theme","Its combat is faster than Dark Souls 1 and 2, closer to Bloodborne"]'),
('15dfd122-9dcd-441f-b383-12a8e712b0e8', 'dead-by-daylight', 'Dead by Daylight', 'Four survivors, one killer — a multiplayer horror where every match is a slasher film.', 'One player becomes the Killer; four must repair generators and escape. With iconic horror villains like Michael Myers and Leatherface, tense cat-and-mouse gameplay, and years of new content, Dead by Daylight is the definitive asymmetric horror game.', 'Behaviour Interactive', 'Behaviour Interactive', '2016-06-14', '["Horror","Action","Multiplayer"]', '["Asymmetric","PvP","Multiplayer","Stealth","Slasher"]', '["Online PvP","Voice Chat","Controller Support","Cross-Platform Play"]', '/covers/dead-by-daylight.hero.jpg', '/covers/dead-by-daylight.box.jpg', 80, '$19.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch","Mobile (iOS/Android)"]', '["Online PvP (Asymmetric 4v1)"]', 'M (Mature 17+)', 'Unreal Engine 4', 'N/A', 80, 'Mostly Positive', '60+ million players', 0, 0, '["Best Multiplayer Game 2016 nominee (The Game Awards)"]', '["Licensed killers include Michael Myers, Leatherface, Nemesis, and Vecna","Each match is a slasher film with a different ending","Its fog, generators, and hooks are now genre shorthand","Behavior Interactive added original killers like The Trickster and The Artist"]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('aa252fe8-f40c-409c-b258-9f5ac4700d66', 'death-stranding', 'Death Stranding', 'Connect a fractured America as a legendary deliveryman.', 'In the aftermath of a catastrophe that blurred the line between life and death, sam porter Bridges crosses a hauntingly beautiful landscape to reconnect isolated cities. A one-of-a-kind journey about human connection, from the mind of Hideo Kojima.', 'Kojima Productions', 'Sony Interactive Entertainment', '2020-07-14', '["Adventure","Action"]', '["Open World","Story Rich","Single-player","Sci-fi","Atmospheric"]', '["Single-player","Async Multiplayer","Controller Support","Achievements"]', '/covers/death-stranding.hero.jpg', '/covers/death-stranding.box.jpg', 82, '$19.99', 0, '["PC","PlayStation 4/5"]', '["Single-player","Async Multiplayer"]', 'M (Mature 17+)', 'Decima', 'Death Stranding', 82, 'Very Positive', '10+ million copies sold', 40, 105, '["Best Game Direction 2019 (The Game Awards)","Best Score/Music 2019"]', '["Its terrain traversal — balancing cargo while walking — is the core gameplay","Players'' structures appear in each other''s worlds asynchronously","Norman Reedus, Mads Mikkelsen, and Léa Seydoux star in it","A sequel, Death Stranding 2, was announced at The Game Awards 2022"]'),
('c7696fcc-edf4-4b6e-b183-e546ce0a933b', 'devil-may-cry-5', 'Devil May Cry 5', 'Over-the-top stylish action from the masters of the genre.', 'Three demon hunters — Nero, Dante, and the mysterious V — wage war against the demonic invasion of Red Grave City. With impossibly fluid combat, deep style rankings, and pure arcade spectacle, DMC5 is the pinnacle of character-action games.', 'Capcom', 'Capcom', '2019-03-08', '["Action","Adventure"]', '["Character Action","Stylish","Third-Person","Fast-Paced","Boss Fights"]', '["Single-player","Online PvP","Controller Support","Achievements"]', '/covers/devil-may-cry-5.hero.jpg', '/covers/devil-may-cry-5.box.jpg', 89, '$29.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'M (Mature 17+)', 'RE Engine', 'Devil May Cry', 89, 'Very Positive', '8+ million copies sold', 11, 75, '["Best Action Game 2019 nominee (The Game Awards)"]', '["Its style meter grades attacks from \"D\" to \"SSS\"","V, a new character, fights with summoned beasts instead of weapons","The Special Edition added Vergil as a playable character","Its soundtrack adapts to how stylishly the player fights"]'),
('521b8936-f7d5-4c76-baf6-abe8fac48503', 'doom-eternal', 'DOOM Eternal', 'Rip and tear through hell in the most aggressive shooter ever made.', 'The legions of Hell have invaded Earth. As the Doom Slayer, you are the only thing standing between humanity and extinction. Chain together glory kills, devastating weapons, and relentless movement in a power-fantasy shooter that never lets up.', 'id Software', 'Bethesda Softworks', '2020-03-20', '["Shooter","Action"]', '["FPS","Fast-Paced","Single-player","Metal","Difficult"]', '["Single-player","Online PvP","Controller Support","Achievements"]', '/covers/doom-eternal.png', '/covers/doom-eternal.png', 90, '$29.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player","Online PvP (Battlemode)"]', 'M (Mature 17+)', 'id Tech 7', 'Doom', 88, 'Very Positive', '10+ million copies sold', 14, 27, '["Best Action Game 2020 (multiple outlets)","Game of the Year 2020 nominee"]', '["Its \"Demon Slayer\" combat loop was designed to feel like a first-person action figure set","Mick Gordon, the composer, built the soundtrack with analog synthesizers and guitar feedback","The Series X/S versions run at 120 fps in performance mode","It runs on Nintendo Switch thanks to a port by Panic Button"]'),
('f4450e91-f466-4125-ad74-00b4590066b5', 'ea-sports-fc-24', 'EA Sports FC 24', 'The world''s game, with millions of players and the most realistic football yet.', 'Formerly FIFA, EA Sports FC 24 brings authentic football with real clubs, players, and leagues from around the world. With HyperMotionV technology, playing styles modeled on real pros, and modes like Ultimate Team and Career, it''s the definitive football experience.', 'EA Vancouver', 'EA Sports', '2023-09-29', '["Sports","Simulation"]', '["Football","Multiplayer","PvP","Licensed","Ultimate Team"]', '["Single-player","Online PvP","Local Co-op","Controller Support","Cross-Platform Play"]', '/covers/ea-sports-fc-24.hero.jpg', '/covers/ea-sports-fc-24.box.jpg', 78, '$69.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player","Online PvP","Online Co-op"]', 'E (Everyone)', 'In-house (EA Frostbite)', 'FIFA / EA Sports FC', 62, 'Mostly Negative (Steam) / Positive (console)', 'The best-selling sports game franchise in history', 0, 0, '["Guinness World Record for best-selling sports game franchise (as FIFA)"]', '["It was the first entry after EA and FIFA ended their 30-year partnership","HyperMotionV technology captures real match data from 180 pro matches","Its \"Ultimate Team\" mode remains one of gaming''s largest economies","The switch from FIFA to FC cost EA the World Cup license but freed it to rename clubs"]'),
('d12f3941-312f-423e-8988-5a8efbae6a3a', 'elden-ring', 'Elden Ring', 'A vast fantasy world of wonder and peril awaits in FromSoftware''s biggest adventure yet.', 'Rise, Tarnished, and be guided by grace to brandish the power of the Elden Ring. Explore the Lands Between, a breathtaking world filled with peril and wonder, and face demigods to become an Elden Lord. With deep, challenging combat and a vast open world co-created with George R. R. Martin, Elden Ring is a landmark action RPG.', 'FromSoftware', 'Bandai Namco Entertainment', '2022-02-25', '["Action","RPG","Adventure"]', '["Open World","Souls-like","Difficult","Dark Fantasy","Story Rich"]', '["Single-player","Online Co-op","Online PvP","Controller Support","Achievements"]', '/covers/elden-ring.hero.jpg', '/covers/elden-ring.box.jpg', 96, '$59.99', 1, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player","Online PvP","Online Co-op","Async Multiplayer"]', 'M (Mature 17+)', 'In-house (FromSoftware)', 'Souls', 96, 'Overwhelmingly Positive', '25+ million copies sold; one of the best-selling games of all time', 60, 132, '["Game of the Year 2022 (The Game Awards)","Best Art Direction 2022","Best RPG 2022 (Golden Joystick)"]', '["Sold 12 million copies in under a month, faster than any FromSoftware game","Hidetaka Miyazaki collaborated with George R. R. Martin on the world''s lore","Its horse, Torrent, cannot die — only be resummoned","Speedrunners have beaten the game in under 3 minutes"]'),
('381001e9-b9c1-4627-b634-bbd34a08d9a2', 'fall-guys', 'Fall Guys', 'Wobble, tumble, and scramble through chaotic obstacle-course battle royale.', 'Race through wild obstacle courses, bounce through team games, and survive elimination rounds against dozens of others — all as a adorable bean person. Free to play and irresistibly silly, Fall Guys is pure party-game joy.', 'Mediatonic', 'Epic Games', '2020-08-04', '["Party","Action","Free to Play"]', '["Battle Royale","Multiplayer","PvP","Family Friendly","Funny"]', '["Online PvP","Cross-Platform Play","Controller Support","Leaderboards"]', '/covers/fall-guys.hero.jpg', '/covers/fall-guys.box.jpg', 80, 'Free', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Online PvP","Online Co-op"]', 'E (Everyone)', 'Unreal Engine 4', 'N/A', 80, 'Mostly Positive', '50+ million players in its first two weeks', 0, 0, '["Best Multiplayer Game 2020 nominee (The Game Awards)"]', '["Its bean-shaped characters became instant memes","It launched free on PlayStation Plus, boosting it to record players","Mediatonic was acquired by Epic Games in 2021","Its crossover skins include Sonic, Godzilla, and Spider-Man"]'),
('9d32609e-58df-4ca5-83e5-8d67da09890e', 'fortnite', 'Fortnite', 'The cultural phenomenon battle royale with endless crossovers and modes.', 'Drop in, gear up, and be the last one standing in this massively popular battle royale. With constant content updates, wild collaborations, creative mode, and a vibrant, cartoonish style, Fortnite is free-to-play fun that has become a global social hangout.', 'Epic Games', 'Epic Games', '2017-07-25', '["Shooter","Action","Free to Play"]', '["Battle Royale","Multiplayer","PvP","Building","Team-Based"]', '["Online PvP","Cross-Platform Play","Voice Chat","Controller Support"]', '/covers/fortnite.png', '/covers/fortnite.png', 80, 'Free', 1, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch","Mobile (via cloud)"]', '["Online PvP","Online Co-op","Squad-based (Trios, Duos, Squads)"]', 'T (Teen)', 'Unreal Engine 5', 'Fortnite', 78, 'Positive (not on Steam)', '500+ million registered players; one of the most-played games in history', 0, 0, '["Best Multiplayer Game 2018 (The Game Awards)","Best Ongoing Game 2019"]', '["Travis Scott''s 2020 in-game concert drew over 12 million live viewers","Its battle royale mode was built in two months by a small internal team","It popularized the \"battle pass\" model now used across the industry","Players have recreated entire cities, movie sets, and working arcade machines in Creative mode"]'),
('f9a44543-433d-4fa0-b14f-c68e4c536de5', 'forza-horizon-5', 'Forza Horizon 5', 'Your epic Horizon adventure in the vibrant evolving open world of Mexico.', 'Explore the diverse landscapes of Mexico in the ultimate open-world racing adventure. Drive hundreds of world-class cars through living deserts, jungles, and historic cities, with stunning graphics, endless events, and a joyful celebration of speed and cars.', 'Playground Games', 'Xbox Game Studios', '2021-11-05', '["Racing","Sports","Action"]', '["Open World","Multiplayer","Driving","Beautiful","Fast-Paced"]', '["Single-player","Online PvP","Online Co-op","Controller Support","Cloud Saves","Achievements"]', '/covers/forza-horizon-5.hero.jpg', '/covers/forza-horizon-5.box.jpg', 92, '$59.99', 1, '["PC","PlayStation 5","Xbox One/Series X|S"]', '["Single-player","Online PvP","Online Co-op"]', 'E (Everyone)', 'ForzaTech', 'Forza', 92, 'Very Positive', '40+ million players; the biggest launch in Xbox history', 20, 120, '["Best Sports/Racing 2021 (The Game Awards)","BAFTA nominee 2022"]', '["Its Mexico map is one of the most diverse racing game worlds ever, with volcano, jungle, and desert","The Forzavista mode lets players explore every car in photorealistic detail","It supports ray tracing on console and PC","Its festival hub lets players build custom courses for friends"]'),
('62aaca07-dd67-4e76-8a16-366533fd5267', 'garrys-mod', 'Garry''s Mod', 'A physics sandbox where the only limit is your imagination.', 'There are no goals — just you, a world of physics objects, and every tool you need. Play thousands of community-made game modes, from prop hunt to Trouble in Terrorist Town. Garry''s Mod is the ultimate creative playground and a party-game institution.', 'Facepunch Studios', 'Facepunch Studios', '2006-11-29', '["Sandbox","Indie"]', '["Physics","Creative","Multiplayer","Modding","Comedy"]', '["Single-player","Online Co-op","Online PvP","Steam Workshop"]', '/covers/garrys-mod.hero.jpg', '/covers/garrys-mod.box.jpg', 88, '$9.99', 0, '["PC","macOS","Linux"]', '["Single-player","Online Co-op","Online PvP"]', 'M (Mature 17+)', 'Source', 'N/A', 88, 'Very Positive', '20+ million copies sold', 0, 0, '["A cultural institution with over a decade of community content"]', '["It started as a free mod called Garry''s Mod 9","The \"Trouble in Terrorist Town\" mode inspired Among Us'' deduction gameplay","Its Prop Hunt mode became its own standalone game","The iconic \"Dr. Kleiner\" NPC model is reused in thousands of community videos"]'),
('0b7b7e53-4903-4683-afa5-18f6cfad574d', 'ghost-of-tsushima', 'Ghost of Tsushima', 'Become the Ghost in a stunning open-world samurai epic.', 'In 1274, a Mongol invasion has devastated Tsushima. As samurai Jin Sakai, you must forge a new path — breaking tradition to fight with stealth and cunning. With gorgeous wind-guided exploration and cinematic sword combat, this is one of the most beautiful games ever made.', 'Sucker Punch Productions', 'Sony Interactive Entertainment', '2020-07-17', '["Action","Adventure"]', '["Open World","Samurai","Story Rich","Beautiful","Stealth"]', '["Single-player","Controller Support","Photo Mode","Achievements"]', '/covers/ghost-of-tsushima.hero.jpg', '/covers/ghost-of-tsushima.box.jpg', 83, '$59.99', 1, '["PC","PlayStation 4/5"]', '["Single-player"]', 'M (Mature 17+)', 'In-house (Sucker Punch engine)', 'N/A', 83, 'Very Positive', '13+ million copies sold', 27, 60, '["Players'' Voice 2020 (The Game Awards)","Best Art Direction nominee 2020"]', '["The wind literally guides players — no quest markers on screen","A fan petition asked Sony for a God of War-style exploration mode; it got one","Its multiplayer Legends mode was added free post-launch","The island of Iki in the DLC is based on a real Mongol invasion site"]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('6011fc29-2b04-4914-85af-bc3a6e0b6851', 'god-of-war-ragnarok', 'God of War Ragnarök', 'Kratos and Atreus journey through the Nine Realms as the end times approach.', 'The epic conclusion to the Norse saga. Father and son face the oncoming Ragnarök, traveling through breathtaking realms, battling gods and monsters, and grappling with what it means to be a father, a son, and a warrior. Combat is visceral, the storytelling is superb, and the visuals are stunning.', 'Santa Monica Studio', 'Sony Interactive Entertainment', '2022-11-09', '["Action","Adventure","RPG"]', '["Mythology","Story Rich","Third-Person","Single-player","Beautiful"]', '["Single-player","Controller Support","Achievements","Photo Mode"]', '/covers/god-of-war-ragnarok.jpg', '/covers/god-of-war-ragnarok.jpg', 94, '$59.99', 0, '["PC","PlayStation 4/5"]', '["Single-player"]', 'M (Mature 17+)', 'In-house (Santa Monica Studio)', 'God of War', 94, 'Overwhelmingly Positive', '15+ million copies sold; a flagship PlayStation exclusive', 26, 52, '["Best Narrative 2022 (The Game Awards)","Best Score and Music 2022","BAFTA Audio Achievement 2023"]', '["Its one-shot camera means the game never cuts during gameplay","Kratos was recast with Christopher Judge, best known as Teal''c in Stargate SG-1","The 2018 prequel won Game of the Year 2018; Ragnarok was its direct sequel","Squirrel Ratatoskr was voiced by Robot Chicken''s Seth Green"]'),
('e283d6ce-556c-4c8e-8475-92d50c34dc45', 'grand-theft-auto-v', 'Grand Theft Auto V', 'A sprawling satirical open world of crime and opportunity in Los Santos.', 'Follow three very different criminals — a retired bank robber, a street hustler, and a psychotic lunatic — through the sun-soaked city of Los Santos. With a massive open world, razor-sharp satire, endless activities, and the ever-popular GTA Online, GTA V remains one of the most played games ever made.', 'Rockstar North', 'Rockstar Games', '2013-09-17', '["Action","Adventure"]', '["Open World","Crime","Third-Person","Multiplayer","Satire"]', '["Single-player","Online PvP","Online Co-op","Controller Support","Achievements"]', '/covers/grand-theft-auto-v.png', '/covers/grand-theft-auto-v.png', 96, '$29.99', 0, '["PC","PlayStation 3/4/5","Xbox 360/One/Series X|S"]', '["Single-player","Online PvP (GTA Online)"]', 'M (Mature 17+)', 'RAGE', 'Grand Theft Auto', 97, 'Very Positive', '200+ million copies sold; the second best-selling video game of all time', 31, 97, '["Game of the Year 2013 (multiple outlets, including The Game Awards)"]', '["Three protagonists was a first for the series and a technical feat","Its music score blends hip-hop, rock, and electronic for every radio station","GTA Online''s Heists update was delayed so long it became a running joke","The game world, Los Santos, is bigger than the combined maps of GTA IV, San Andreas, and Red Dead Redemption"]'),
('e8b23de3-bf5a-45b7-9a92-591f2126269a', 'hades', 'Hades', 'Defy the god of the dead in this award-winning rogue-like dungeon crawler.', 'Battle out of the Greek underworld as the immortal prince of the Underworld, wielding the powers of Olympus in a story-rich, endlessly replayable escape attempt. Every death brings you closer to victory in this critically-acclaimed blend of fast action and rich narrative.', 'Supergiant Games', 'Supergiant Games', '2020-09-17', '["Action","Roguelite","Indie"]', '["Roguelike","Dungeon Crawler","Mythology","Story Rich","Fast-Paced"]', '["Single-player","Controller Support","Cloud Saves","Achievements"]', '/covers/hades.hero.jpg', '/covers/hades.box.jpg', 93, '$24.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'T (Teen)', 'In-house (Cheats & Engines / custom C#)', 'Hades', 93, 'Overwhelmingly Positive', '10+ million copies sold; a genre-defining roguelike', 21, 99, '["Best Action Game 2020 (The Game Awards)","Best Indie Game 2020","Hugo Award for Best Interactive Media 2021"]', '["It was the first video game ever to win a Hugo Award","Every death triggers new dialogue — over 20,000 voice lines total","The story of escaping the underworld is drawn straight from Greek mythology","Its voice cast included Logan Cunningham, long-time Supergiant collaborator"]'),
('9fd76a9b-59ae-41e0-9836-cbe4c562c96a', 'hogwarts-legacy', 'Hogwarts Legacy', 'Live the unwritten and attend Hogwarts in the 1800s.', 'Your character is a student who holds the key to an ancient secret. Explore an open world of Hogwarts, Hogsmeade, and the surrounding highlands, learn spells, brew potions, tame magical beasts, and shape your own legacy in the wizarding world — a full century before Harry Potter''s story.', 'Avalanche Software', 'Warner Bros. Games', '2023-02-10', '["RPG","Action","Adventure"]', '["Open World","Magic","Fantasy","Single-player","Story Rich"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/hogwarts-legacy.hero.jpg', '/covers/hogwarts-legacy.box.jpg', 84, '$59.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'T (Teen)', 'Unreal Engine 4', 'Wizarding World', 84, 'Mostly Positive', '30+ million copies sold', 25, 70, '["Best Fantasy Game 2023 (The Game Awards nominee)","Golden Joystick PlayStation Game of the Year 2023"]', '["It is set in the 1890s, long before Harry Potter''s era","Players can tame and ride Hippogriffs and Thestrals","The Room of Requirement serves as a base-building hub","It sold 12 million copies in its first two weeks despite controversy"]'),
('426dbdd2-8504-4f4f-bc20-3c9a25f004bd', 'hollow-knight', 'Hollow Knight', 'A haunting, hand-drawn adventure through the ruins of a forgotten kingdom.', 'Explore twisting caverns, ancient cities, and deadly wastes in this atmospheric Metroidvania. Battle tainted creatures, befriend bizarre bugs, and uncover the ancient mystery at the heart of Hallownest. With beautiful hand-drawn art and challenging, precise combat, Hollow Knight is a modern classic.', 'Team Cherry', 'Team Cherry', '2017-02-24', '["Action","Adventure","Indie"]', '["Metroidvania","Difficult","Hand-drawn","Atmospheric","Exploration"]', '["Single-player","Controller Support","Cloud Saves","Achievements"]', '/covers/hollow-knight.hero.jpg', '/covers/hollow-knight.box.jpg', 91, '$14.99', 1, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player"]', 'E10+ (Everyone 10+)', 'Unity', 'Hollow Knight', 90, 'Overwhelmingly Positive', '15+ million copies sold', 27, 55, '["Best Indie Game 2017 (multiple outlets)","GDC Award for Best Visual Art 2018"]', '["It was funded on Kickstarter in 2014 with just $57,000","Team Cherry, the developer, is a three-person studio from Adelaide, Australia","Its hand-drawn art took years and inspired thousands of fan animations","The game''s lore is deliberately left for players to piece together"]'),
('ff0d61a3-08d1-4325-b133-7cc9b1cd760d', 'it-takes-two', 'It Takes Two', 'A mind-bending co-op adventure built entirely around two-player play.', 'Play as the clashing couple Cody and May, turned into dolls and trapped in a fantastical world. Forced to work together through wildly varied gameplay and creative challenges, this pure co-op adventure requires two players and delivers an unforgettable ride about teamwork and love.', 'Hazelight Studios', 'Electronic Arts', '2021-03-26', '["Action","Adventure","Platformer"]', '["Co-op","Puzzle","Creative","Split-screen","Story Rich"]', '["Online Co-op","Local Co-op","Split-screen","Controller Support","Achievements"]', '/covers/it-takes-two.hero.jpg', '/covers/it-takes-two.box.jpg', 89, '$39.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Local Co-op","Online Co-op (Friend''s Pass)"]', 'T (Teen)', 'Unreal Engine 4', 'N/A', 89, 'Very Positive', '20+ million copies sold', 12, 15, '["Game of the Year 2021 (The Game Awards)","Best Multiplayer 2021","BAFTA Best Game 2022"]', '["It can only be played in co-op — no single-player mode exists","The Friend''s Pass lets one buyer play with a friend for free","Its story is about a married couple turned into dolls working through divorce","A companion book, \"It Takes Two: An Adventure in Creativity\", accompanied its release"]'),
('8f87fa0f-54f4-4900-a44b-fc7ca87eb58f', 'left-4-dead-2', 'Left 4 Dead 2', 'The definitive four-player zombie co-op shooter.', 'Team up with three friends and blast through hordes of zombies in the legendary co-op shooter. With distinct special infected, endless replayability, and campaigns across the South, L4D2 remains the greatest zombie game ever made.', 'Valve', 'Valve', '2009-11-17', '["Shooter","Action"]', '["Zombies","Co-op","FPS","Multiplayer","Classic"]', '["Online Co-op","Local Co-op","Online PvP","Controller Support","Steam Workshop"]', '/covers/left-4-dead-2.hero.jpg', '/covers/left-4-dead-2.box.jpg', 89, '$9.99', 0, '["PC","Xbox 360"]', '["Online Co-op","Local Co-op (Split-screen)","Online PvP"]', 'M (Mature 17+)', 'Source', 'Left 4 Dead', 89, 'Overwhelmingly Positive', '15+ million copies sold', 0, 0, '["Best Multiplayer Game 2009 (multiple outlets)"]', '["It was released just one year after the original — an unusually fast sequel","The AI \"Director\" adjusts pacing, spawns, and items to each play session","Its community Workshop adds thousands of custom campaigns","The four survivors of the first game return as playable characters in DLC"]'),
('9c6907fc-0260-403f-b6f6-997e34d746a4', 'minecraft', 'Minecraft', 'Build anything you can imagine in the world''s most popular sandbox game.', 'Minecraft is a sandbox game of infinite creativity. Mine blocks, craft tools, build towering structures, and survive against monsters in a procedurally generated world of endless possibility. Play solo, join friends online, or explore countless community-made worlds and mods — there is truly something for everyone in this modern classic.', 'Mojang Studios', 'Mojang Studios', '2011-11-18', '["Sandbox","Survival","Adventure"]', '["Crafting","Open World","Multiplayer","Creative","Block-Based"]', '["Single-player","Online Co-op","Local Co-op","Cross-Platform Play","Controller Support","Cloud Saves"]', '/covers/minecraft.png', '/covers/minecraft.png', 93, '$26.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch","Mobile (iOS/Android)"]', '["Single-player","Online Co-op","Local Co-op","Online PvP"]', 'E10+ (Everyone 10+)', 'In-house (Java / Bedrock Engine)', 'Minecraft', 93, 'Very Positive', '300+ million copies sold; the best-selling video game of all time', 0, 3500, '["Named the best-selling game ever by Guinness World Records"]', '["Creepers were created by accident when a coding error made a pig too tall and too long","Its soundtrack by C418 is widely considered one of gaming''s most iconic","There are over 140 million monthly active players worldwide","Players have built working computers, hard drives, and even 1-bit CPUs inside the game"]'),
('c3597765-81c6-4927-9f80-e451012b770a', 'monster-hunter-world', 'Monster Hunter: World', 'Hunt colossal beasts in a living ecosystem of predators and prey.', 'Take on the role of a hunter stalked by gigantic monsters in vast, living landscapes. Track, trap, and battle fearsome creatures, craft ever-stronger gear from your kills, and team up with up to three friends in the most successful game in Capcom''s history.', 'Capcom', 'Capcom', '2018-01-26', '["Action","RPG"]', '["Co-op","Hunting","Crafting","Difficult","Third-Person"]', '["Single-player","Online Co-op","Voice Chat","Controller Support","Achievements"]', '/covers/monster-hunter-world.hero.jpg', '/covers/monster-hunter-world.box.jpg', 90, '$29.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player","Online Co-op"]', 'T (Teen)', 'MT Framework', 'Monster Hunter', 90, 'Very Positive', '25+ million copies sold; Capcom''s best-selling game ever', 48, 165, '["Best RPG 2018 nominee (The Game Awards)","Japan Game Awards 2018"]', '["It was the first Monster Hunter designed for a global audience","Each monster has an ecosystem — they hunt, eat, and fight each other","Its Palico cat companions can be customized with equipment","The Iceborne expansion added a whole new arctic continent"]'),
('d92a912c-50c4-43f8-aba0-24fb3cd9300e', 'nba-2k24', 'NBA 2K24', 'The most authentic basketball simulation, with all your favorite teams and stars.', 'Experience NBA basketball with lifelike graphics, authentic rosters, and deep game modes. Build a dynasty in MyCareer, relive Kobe Bryant''s legendary career in Mamba Moments, and dominate the hardwood in this year''s premier basketball sim.', 'Visual Concepts', '2K Sports', '2023-09-08', '["Sports","Simulation"]', '["Basketball","Multiplayer","PvP","Licensed","Career"]', '["Single-player","Online PvP","Local Co-op","Controller Support","Cross-Platform Play"]', '/covers/nba-2k24.hero.jpg', '/covers/nba-2k24.box.jpg', 67, '$59.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player","Online PvP","Online Co-op"]', 'E (Everyone)', 'In-house (Visual Concepts engine)', 'NBA 2K', 67, 'Mostly Negative (Steam)', 'The best-selling basketball video game franchise', 0, 0, '["Sports Game of the Year nominee (multiple outlets, historic)"]', '["Kobe Bryant graces the cover for the Mamba Moments mode","ProPLAY technology animates real NBA footage into gameplay","Its MyCareer mode lets players live out an NBA story from high school to the Hall of Fame","The W mode focuses on WNBA careers for the first time in the series"]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('13985fec-f8b9-4ef4-ad5d-628c3e41660a', 'overwatch-2', 'Overwatch 2', 'A team-based hero shooter with a vibrant cast of unique heroes.', 'Team up and pick your hero from a diverse roster of tank, damage, and support characters, each with their own abilities and personality. With fast-paced objective-based matches and colorful, competitive action, Overwatch 2 is a polished, always-evolving hero shooter.', 'Blizzard Entertainment', 'Blizzard Entertainment', '2022-10-04', '["Shooter","Action","Free to Play"]', '["Hero Shooter","Multiplayer","PvP","Team-Based","Competitive"]', '["Online PvP","Cross-Platform Play","Voice Chat","Controller Support"]', '/covers/overwatch-2.jpg', '/covers/overwatch-2.jpg', 79, 'Free', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Online PvP","Co-op (PvE missions)"]', 'T (Teen)', 'In-house (Blizzard engine)', 'Overwatch', 80, 'Mixed (Steam) / Positive (Battle.net)', '35+ million players in its first year; one of the largest shooter communities', 0, 0, '["Best Multiplayer Game 2022 (The Game Awards, for launch momentum)"]', '["It replaced the original Overwatch''s 6v6 format with 5v5 squads","Every hero has a unique ultimate that can change the course of a team fight","It became free-to-play in October 2022 with a seasonal battle pass model","Kiriko''s \"Kitsune Rush\" ultimate was inspired by Japanese folklore"]'),
('a93cb0c6-96e2-4a89-9138-71fa3efe407f', 'persona-5-royal', 'Persona 5 Royal', 'A stylish JRPG about phantom thieves stealing corrupt hearts.', 'Lead a group of vigilante students who moonlight as the Phantom Thieves, entering a supernatural realm to change the hearts of corrupt adults. With razor-sharp style, a deep turn-based combat system, unforgettable characters, and a hundred hours of story, Persona 5 Royal is a modern JRPG landmark.', 'Atlus', 'Atlus', '2019-10-31', '["RPG","Adventure","Simulation"]', '["Turn-Based","Anime","Story Rich","Stylish","School Life"]', '["Single-player","Controller Support","Achievements"]', '/covers/persona-5-royal.hero.jpg', '/covers/persona-5-royal.box.jpg', 95, '$59.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'M (Mature 17+)', 'In-house (Atlus engine)', 'Persona', 95, 'Overwhelmingly Positive', '8+ million copies sold (Persona 5 family)', 103, 145, '["Best RPG 2017 (multiple outlets, original release)","NAACP Image Award nominee for its jazz soundtrack"]', '["The soundtrack by Shoji Meguro blends acid jazz with rock and opera","Its calendar system means every in-game day matters","Persona 5''s cast became so popular they crossed over into Smash Bros","The Royal version adds 30 hours of new content and a third semester"]'),
('481a12ad-a380-4596-bc77-59e07178874f', 'portal-2', 'Portal 2', 'A landmark puzzle game of portals, physics, and perfect comedy writing.', 'Wield a portal gun to bend space, solve ingeniously designed test chambers, and unravel a story voiced by one of gaming''s greatest villains. With a full separate co-op campaign, Portal 2 remains the gold standard for puzzle games — and for video game humor.', 'Valve', 'Valve', '2011-04-19', '["Puzzle","Adventure","Action"]', '["First-Person","Single-player","Co-op","Comedy","Sci-fi"]', '["Single-player","Local Co-op","Online Co-op","Controller Support","Cloud Saves","Achievements"]', '/covers/portal-2.hero.jpg', '/covers/portal-2.box.jpg', 93, '$9.99', 0, '["PC","PlayStation 3","Xbox 360","Nintendo Switch (Portal: Companion Collection)"]', '["Single-player","Online Co-op","Local Co-op"]', 'E10+ (Everyone 10+)', 'Source', 'Portal', 95, 'Overwhelmingly Positive', '10+ million copies sold', 8, 12, '["BAFTA Best Game 2012","Game of the Year 2011 (multiple outlets)"]', '["Stephen Merchant and J.K. Simmons voiced key characters","Its co-op campaign has an entirely separate story from the single-player","GLaDOS''s passive-aggressive humor is considered one of gaming''s best-written villains","A Valve engineer once hid a Portal 2 reference in an Arduino firmware update"]'),
('544d3d8b-3f84-490a-9d2a-ee111be17cd8', 'pubg-battlegrounds', 'PUBG: Battlegrounds', 'The original battle royale where 100 players fight to be the last one standing.', 'Drop onto an island, scavenge for weapons, and outlast 99 other players in the game that started the battle royale craze. With realistic gunplay, shrinking play zones, and tense, tactical firefights, every PUBG match is a story of survival.', 'Krafton', 'Krafton', '2017-12-21', '["Shooter","Action","Free to Play"]', '["Battle Royale","Multiplayer","PvP","Realistic","Survival"]', '["Online PvP","Voice Chat","Cross-Platform Play","Controller Support"]', '/covers/pubg-battlegrounds.hero.jpg', '/covers/pubg-battlegrounds.box.jpg', 83, 'Free', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Mobile (iOS/Android)"]', '["Online PvP","Squad-based (Squads, Duos)"]', 'T (Teen)', 'Unreal Engine 4', 'PUBG', 83, 'Mostly Positive', '75+ million copies sold; 350+ million mobile players', 0, 0, '["Best Multiplayer Game 2017 nominee (The Game Awards)","Esports Game of the Year 2018 nominee"]', '["It popularized the battle royale genre and inspired Fortnite and Apex","Brendan Greene, \"PlayerUnknown\", created the mode from Arma mods","The blue zone — a shrinking wall of electricity — became genre standard","PUBG Mobile has been downloaded over 1 billion times"]'),
('2aa7db41-4cfd-4276-9c57-b0ce0feae525', 'red-dead-redemption-2', 'Red Dead Redemption 2', 'America, 1899. The end of the Wild West era is near.', 'Arthur Morgan and the Van der Linde gang are on the run. This sprawling epic of life in America''s unforgiving heartland features a massive open world, deep characters, and a story of loyalty and betrayal. Every detail of this living world is crafted to draw you into the dying days of the outlaw era.', 'Rockstar Games', 'Rockstar Games', '2018-10-26', '["Action","Adventure"]', '["Open World","Western","Story Rich","Third-Person","Atmospheric"]', '["Single-player","Online PvP","Controller Support","Achievements"]', '/covers/red-dead-redemption-2.hero.jpg', '/covers/red-dead-redemption-2.box.jpg', 97, '$59.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player","Online PvP (Red Dead Online)"]', 'M (Mature 17+)', 'RAGE', 'Red Dead', 97, 'Very Positive', '65+ million copies sold; one of the best-selling games of all time', 50, 178, '["Best Narrative 2018 (The Game Awards)","Best Score/Music 2018","BAFTA Best Game 2019"]', '["Every NPC has a daily routine, including going to work and eating dinner","Animal testicles shrink in cold weather — a detail widely reported by players","Its homage to the original Red Dead Redemption is woven into the story","RDR2''s horse bonding system tracks care, grooming, and rider trust"]'),
('4e2a1c43-f039-4379-934f-dd2310e093fd', 'resident-evil-4-remake', 'Resident Evil 4 (2023)', 'Survival is just the beginning in this reimagining of a survival horror classic.', 'Special agent Leon S. Kennedy is sent to rescue the U.S. President''s daughter from a sinister cult in rural Spain. This ground-up remake of the legendary survival horror game blends tense combat, resource management, and modernized storytelling into a relentless, heart-pounding experience.', 'Capcom', 'Capcom', '2023-03-24', '["Action","Horror","Shooter"]', '["Survival Horror","Remake","Third-Person","Story Rich","Single-player"]', '["Single-player","Controller Support","Cloud Saves","Achievements"]', '/covers/resident-evil-4-remake.hero.jpg', '/covers/resident-evil-4-remake.box.jpg', 93, '$39.99', 1, '["PC","PlayStation 4/5","Xbox Series X|S"]', '["Single-player"]', 'M (Mature 17+)', 'RE Engine', 'Resident Evil', 93, 'Overwhelmingly Positive', '7+ million copies sold within a year', 16, 30, '["Best VR/Action Game 2023 (The Game Awards)","Golden Joystick Ultimate Game of the Year 2023"]', '["The original 2005 Resident Evil 4 is widely considered one of the greatest games ever","The remake overhauls combat with modern parries and knife durability","Ashley''s AI companion was rebuilt to feel like a real partner, not a burden","Ada Wong''s Separate Ways campaign was re-released as DLC in 2023"]'),
('6f2b43f0-5d7c-4856-a52e-01d46a9c051f', 'rocket-league', 'Rocket League', 'Soccer meets driving in the high-flying, rocket-powered sports phenomenon.', 'Spring for the ball, wall-drive, backflip, and score impossible aerial goals in the world''s most exciting vehicle-soccer hybrid. Free to play with fast matches, deep mechanics, and a thriving esports scene, Rocket League is endlessly replayable competition.', 'Psyonix', 'Psyonix', '2015-07-07', '["Sports","Racing","Free to Play"]', '["Multiplayer","PvP","Competitive","Team-Based","Fast-Paced"]', '["Online PvP","Cross-Platform Play","Split-screen","Controller Support","Leaderboards"]', '/covers/rocket-league.hero.jpg', '/covers/rocket-league.box.jpg', 86, 'Free', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Online PvP","Local Co-op (Split-screen)"]', 'E (Everyone)', 'Unreal Engine 3/4', 'N/A', 86, 'Very Positive', '90+ million players worldwide', 0, 0, '["Best Sports Game 2015 (The Game Awards)","Best Independent Game 2015 nominee"]', '["It was made by a small studio in San Diego, later bought by Epic Games","Its \"ranked\" seasons run in competitive playlists year-round","Cars can be customized with over 1,000 cosmetic items","The rocket-powered car-soccer idea came from a 2008 game called Supersonic Acrobatic Rocket-Powered Battle-Cars"]'),
('231f5dfe-8b3e-4604-a475-f46e05e8c14d', 'rust', 'Rust', 'Survive, build, and betray in the world''s most brutal survival game.', 'Wake up naked on a beach with a rock and a torch. Gather, build, raid, and defend against a world of ruthless players in the multiplayer survival game that made betrayal an art form. Harsh, unforgiving, and endlessly compelling.', 'Facepunch Studios', 'Facepunch Studios', '2018-02-08', '["Survival","Action"]', '["Multiplayer","PvP","Crafting","Open World","Base Building"]', '["Online PvP","Online Co-op","Voice Chat","Cloud Saves"]', '/covers/rust.hero.jpg', '/covers/rust.box.jpg', 86, '$39.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Online PvP","Online Co-op"]', 'M (Mature 17+)', 'Unity', 'Rust', 86, 'Very Positive', '16+ million copies sold', 0, 0, '["Best Survival Game 2018 (multiple outlets)"]', '["Every player''s skin color is assigned randomly and permanently","Its monthly forced server wipes reset the entire world","Raiding other players'' bases is the endgame for most clans","It began as a DayZ-inspired clone, then became its own brutal identity"]'),
('bd5b5ea3-535e-46db-98a8-efbd93b42462', 'sekiro-shadows-die-twice', 'Sekiro: Shadows Die Twice', 'Hardened ninja combat in a beautifully brutal Sengoku-era Japan.', 'You are a shinobi bound to protect a young lord of an ancient bloodline, facing impossible odds. With precise, rhythm-based sword combat, a rich world of myth and stealth, and some of FromSoftware''s most demanding boss fights, Sekiro rewards mastery like few other games.', 'FromSoftware', 'Activision', '2019-03-22', '["Action","Adventure"]', '["Souls-like","Difficult","Stealth","Historical","Single-player"]', '["Single-player","Controller Support","Achievements"]', '/covers/sekiro-shadows-die-twice.jpg', '/covers/sekiro-shadows-die-twice.jpg', 90, '$59.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player"]', 'M (Mature 17+)', 'In-house (FromSoftware)', 'Souls', 90, 'Overwhelmingly Positive', '10+ million copies sold', 35, 70, '["Game of the Year 2019 (The Game Awards)","Best Action/Adventure 2019"]', '["It trades Souls games'' RPG builds for pure swordsmanship skill","The resurrection mechanic — literally dying twice — gave the game its title","Shinobi prosthetic tools allow creative playstyles akin to a puzzle box","Its score by Yuka Kitamura and Hiroki Kikuta is considered a modern classic"]'),
('73b33020-ef99-49d3-8a83-bc464b39400e', 'civilization-vi', 'Sid Meier''s Civilization VI', 'Build an empire to stand the test of time in the definitive 4X strategy game.', 'Lead a civilization from the first settlement to the space age. Research technologies, wage wars, spread religions, and shape history alongside leaders from across time. The famous "one more turn" hook has never been more addictive.', 'Firaxis Games', '2K Games', '2016-10-21', '["Strategy","Simulation"]', '["Turn-Based","4X","Historical","Single-player","Multiplayer"]', '["Single-player","Online PvP","Online Co-op","Cloud Saves","Achievements"]', '/covers/civilization-vi.hero.jpg', '/covers/civilization-vi.box.jpg', 88, '$59.99', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch","Mobile (iOS/Android)"]', '["Single-player","Online PvP","Online Co-op"]', 'E10+ (Everyone 10+)', 'In-house (Firaxis engine)', 'Civilization', 88, 'Very Positive', '11+ million copies sold', 0, 0, '["Best Strategy Game 2016 nominee (The Game Awards)"]', '["Sean Bean narrates the tech tree — quoting actual historical figures","Every leader has an AI personality that shapes diplomacy","Its \"one more turn\" design is legendary among strategy fans","The Rise and Fall expansion introduced loyal and rebellious cities"]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('e73c1d83-9c4a-4158-aecb-4fc231ac9422', 'stardew-valley', 'Stardew Valley', 'A beloved farming sim where you build the life of your dreams.', 'You''ve inherited your grandfather''s old farm plot in Stardew Valley. Armed with hand-me-down tools, set out to build a new life. Grow crops, raise animals, mine for treasure, befriend townsfolk, and maybe find love in this charming, endlessly relaxing farming adventure with surprising depth.', 'ConcernedApe', 'ConcernedApe', '2016-02-26', '["Simulation","RPG","Indie"]', '["Farming Sim","Cozy","Crafting","Pixel Graphics","Relaxing"]', '["Single-player","Online Co-op","Local Co-op","Controller Support","Cloud Saves","Achievements"]', '/covers/stardew-valley.hero.jpg', '/covers/stardew-valley.box.jpg', 97, '$14.99', 1, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch","Mobile (iOS/Android)"]', '["Single-player","Online Co-op","Local Co-op"]', 'E10+ (Everyone 10+)', 'MonoGame (C#)', 'Stardew Valley', 89, 'Overwhelmingly Positive', '41+ million copies sold; one of the best-selling indie games ever', 80, 160, '["Golden Joystick Breakthrough 2016","BAFTA nominee 2017"]', '["It was created by a single developer, Eric Barone, over four years","Barone drew all the pixel art and wrote all the music himself","The game''s community center replaced a last-minute \"Joja warehouse\" ending","Jas, one of the town''s children, is named after Barone''s sister"]'),
('a10ac461-f52e-41ee-8cb4-597a125691a6', 'team-fortress-2', 'Team Fortress 2', 'Nine ridiculous classes, one legendary team-based shooter.', 'The comic, chaotic, endlessly influential hero shooter. Play as the Scout, the Spy, the Medic, and more in objective-based multiplayer mayhem. With decades of updates, an iconic art style, and a beloved community, TF2 is a true gaming institution.', 'Valve', 'Valve', '2007-10-10', '["Shooter","Action","Free to Play"]', '["Multiplayer","PvP","Team-Based","Classes","Comedy"]', '["Online PvP","Voice Chat","Steam Workshop","Leaderboards"]', '/covers/team-fortress-2.hero.jpg', '/covers/team-fortress-2.box.jpg', 92, 'Free', 0, '["PC","PlayStation 3","Xbox 360"]', '["Online PvP"]', 'M (Mature 17+)', 'Source', 'Team Fortress', 92, 'Very Positive', 'One of the most-played Steam games for 15+ years', 0, 0, '["Best Multiplayer Game 2007 (multiple outlets)","Guinness World Record for most-patched game (2010s)"]', '["Its cartoon art style is based on the work of illustrator J.C. Leyendecker","Every class has a rich comic-book backstory, published free online","The Spy can disguise as any enemy class and backstab for instant kills","Its hat economy became a real phenomenon studied by economists"]'),
('ac96d8cc-99bc-4c5e-a63c-3a2656930c61', 'terraria', 'Terraria', 'Dig, fight, explore, build — a 2D sandbox adventure of endless depth.', 'In Terraria, the world is your canvas and the underground is your playground. Dig for treasure, fight huge bosses, build incredible structures, and craft thousands of items in this charming 2D sandbox. With tons of content and endless replayability, Terraria is a true indie legend.', 'Re-Logic', 'Re-Logic', '2011-05-16', '["Sandbox","Adventure","Indie"]', '["Crafting","2D","Building","Exploration","Boss Fights"]', '["Single-player","Online Co-op","Local Co-op","Controller Support","Cloud Saves"]', '/covers/terraria.jpg', '/covers/terraria.jpg', 83, '$9.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch","Mobile (iOS/Android)"]', '["Single-player","Online Co-op","Local Co-op","Online PvP"]', 'T (Teen)', 'In-house (XNA/FNA)', 'Terraria', 83, 'Overwhelmingly Positive', '44+ million copies sold; one of the best-selling indie games ever', 0, 0, '["Best Indie Game 2011 (IndieDB)","Golden Joystick indie nominee"]', '["It has received over a decade of free content updates — a record for an indie game","The final \"Journey''s End\" update added over 1,000 new items","The Moon Lord is a reference to the Lovecraftian Cthulhu mythos","It started as a Minecraft-meets-Metroid hybrid proposed on a forum"]'),
('a5cde308-f6ea-4dc5-9640-a77d6db1fd03', 'the-last-of-us-part-i', 'The Last of Us Part I', 'A heartbreaking post-apocalyptic journey of survival and love.', 'Joel, a hardened survivor, is hired to smuggle 14-year-old Ellie out of a quarantine zone. What starts as a simple job becomes a brutal journey across a decimated America. With masterful storytelling, tense survival gameplay, and unforgettable characters, The Last of Us is one of gaming''s greatest narratives.', 'Naughty Dog', 'Sony Interactive Entertainment', '2022-09-02', '["Action","Adventure","Horror"]', '["Story Rich","Post-apocalyptic","Single-player","Third-Person","Emotional"]', '["Single-player","Controller Support","Achievements"]', '/covers/the-last-of-us-part-i.hero.jpg', '/covers/the-last-of-us-part-i.box.jpg', 88, '$49.99', 0, '["PC","PlayStation 5"]', '["Single-player"]', 'M (Mature 17+)', 'In-house (Naughty Dog engine)', 'The Last of Us', 88, 'Very Positive', 'Original sold 20+ million; Part I remake sold millions more', 13, 24, '["Original won Game of the Year 2013; remake nominated for accessibility awards"]', '["The remake was rebuilt from scratch with modern lighting and animations","Its infected enemies are based on real Cordyceps fungi","The story of Joel and Ellie is considered a high-water mark for narrative games","The HBO adaptation, starring Pedro Pascal and Bella Ramsey, premiered in 2023"]'),
('854420a7-6f59-4cb8-97d1-be117c7aa31c', 'the-legend-of-zelda-tears-of-the-kingdom', 'The Legend of Zelda: Tears of the Kingdom', 'An epic adventure across the land and skies of Hyrule.', 'In the sequel to Breath of the Wild, Link explores the sprawling skies and deep depths of Hyrule. With new abilities like Ultrahand and Fuse, you can craft weapons, build vehicles, and solve puzzles in a world that rewards creativity like no other.', 'Nintendo EPD', 'Nintendo', '2023-05-12', '["Action","Adventure","RPG"]', '["Open World","Crafting","Puzzle","Story Rich","Exploration"]', '["Single-player","Controller Support"]', '/covers/the-legend-of-zelda-tears-of-the-kingdom.jpg', '/covers/the-legend-of-zelda-tears-of-the-kingdom.jpg', 96, '$69.99', 1, '["Nintendo Switch"]', '["Single-player"]', 'E10+ (Everyone 10+)', 'In-house (Nintendo EPD)', 'The Legend of Zelda', 96, 'Positive (not on Steam)', '20+ million copies sold; fastest-selling Zelda game ever', 59, 250, '["Best Action/Adventure 2023 (The Game Awards)","Players'' Voice 2023"]', '["Its fuse and ultrahand abilities let players build vehicles, machines, and more","The map is roughly triple the size of Breath of the Wild when counting the sky and depths","Nintendo released an official, free trading card of its Master Sword","Players found a way to defeat the final boss in under 2 minutes using creative ability stacking"]'),
('376bd987-40fd-43eb-94df-356adf878d28', 'the-sims-4', 'The Sims 4', 'The world-famous life simulator, where you create and control people.', 'Build homes, design personalities, pursue careers, start families, and tell stories with the most beloved life sim ever made. Free to play with a decade of add-on content, The Sims 4 lets you play with life in any way you can imagine.', 'Maxis', 'Electronic Arts', '2014-09-02', '["Simulation","Casual"]', '["Life Sim","Creative","Building","Relaxing","Single-player"]', '["Single-player","Controller Support","Cloud Saves","Gallery"]', '/covers/the-sims-4.hero.jpg', '/covers/the-sims-4.box.jpg', 76, 'Free', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'T (Teen)', 'In-house (Maxis engine)', 'The Sims', 76, 'Mostly Positive', '70+ million players worldwide', 0, 0, '["Best Simulation Game 2014 (multiple outlets)"]', '["It became free-to-play in October 2022","Its Create-a-Sim introduced customizable body types and skin tones","The Gallery lets players share houses and households worldwide","Emotions — happy, angry, embarrassed — drive its simulation, a first for the series"]'),
('39cc1bf8-37fa-43c1-a4ec-c00adee8ca98', 'the-witcher-3-wild-hunt', 'The Witcher 3: Wild Hunt', 'A story-driven RPG of monster hunting and moral ambiguity.', 'You are Geralt of Rivia, a monster slayer for hire, on a quest to find your adopted daughter in a war-torn world. With rich characters, meaningful choices, breathtaking landscapes, and two massive story expansions, The Witcher 3 set a new standard for open-world RPGs and remains a genre benchmark.', 'CD Projekt Red', 'CD Projekt', '2015-05-19', '["RPG","Adventure","Action"]', '["Open World","Story Rich","Choices Matter","Fantasy","Third-Person"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/the-witcher-3-wild-hunt.jpg', '/covers/the-witcher-3-wild-hunt.jpg', 93, '$49.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'M (Mature 17+)', 'REDengine 3', 'The Witcher', 93, 'Overwhelmingly Positive', '50+ million copies sold; among the best-selling RPGs ever', 105, 189, '["Game of the Year 2015 (The Game Awards)","Golden Joystick Ultimate Game of the Year 2015"]', '["CD Projekt Red promised no DRM and delivered","The Bloody Baron questline is taught in writing courses as an example of branching narrative","Gwent, an in-game card game, became its own standalone game","The game''s \"Evil Incarnate\" ending was voted on by fans in Poland"]'),
('693ca9bb-9c9c-4c54-819a-548f29e3fe5c', 'valheim', 'Valheim', 'A brutal Viking survival saga for one to ten players.', 'Prove your worth to the Norse gods by conquering a procedurally generated world of forests, mountains, and seas. Build longhalls, craft legendary weapons, and summon and slay ancient beasts. Deep survival mechanics and cooperative play make Valheim a phenomenon.', 'Iron Gate AB', 'Coffee Stain Publishing', '2021-02-02', '["Survival","Adventure","Indie"]', '["Co-op","Crafting","Open World","Vikings","Base Building"]', '["Single-player","Online Co-op","Cloud Saves","Steam Workshop"]', '/covers/valheim.hero.jpg', '/covers/valheim.box.jpg', 93, '$19.99', 0, '["PC","Xbox One/Series X|S"]', '["Single-player","Online Co-op (up to 10 players)"]', 'T (Teen)', 'Unity', 'N/A', 93, 'Overwhelmingly Positive', '12+ million copies sold', 60, 150, '["Best Debut Game 2021 nominee (The Game Awards)","Golden Joystick Breakthrough 2021"]', '["It was made by a five-person studio in Sweden","Its procedural worlds are inspired by Norse mythology","Building, farming, and sailing are as important as combat","The name \"Valheim\" refers to the tenth world in Norse mythology"]'),
('3b7b6246-0515-43b5-8ff7-77c5cafd2b05', 'dark-souls-remastered', 'Dark Souls: Remastered', 'The remastered version of the genre-defining dark fantasy action RPG.', 'Lordran is a decaying world of linked kingdoms, and every enemy can kill you in a few hits. The Remastered release runs at 60 fps and includes the Artorias of the Abyss expansion, while keeping the deliberate combat and the world that loops back on itself.', 'FromSoftware', 'Bandai Namco Entertainment', '2018-05-23', '["Action","RPG"]', '["Soulslike","Dark Fantasy","Difficult","Third-Person"]', '["Single-player","Controller Support","Achievements"]', '/covers/dark-souls-remastered.hero.jpg', '/covers/dark-souls-remastered.box.jpg', 84, '$19.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player","Multi-player"]', 'M (Mature 17+)', 'FromSoftware Engine', 'Dark Souls', 84, 'Very Positive', NULL, 44, 100, '[]', '["The original Dark Souls launched in 2011 and turned the phrase prepare to die into a gaming catchphrase.","The Remastered release bundles the Artorias of the Abyss content that was paid DLC in the original.","Lordran is designed so that most areas connect without loading screens."]'),
('15a404ee-1fc4-4055-ac69-1f037ffc2172', 'the-elder-scrolls-v-skyrim', 'The Elder Scrolls V: Skyrim', 'Dragons return to Tamriel and only the Dragonborn can stop them.', 'Skyrim drops you into a frozen province with a civil war, a dragon crisis and hundreds of caves to get lost in. The Special Edition on Steam includes the Dawnguard, Hearthfire and Dragonborn expansions plus updated lighting and mod support.', 'Bethesda Game Studios', 'Bethesda Softworks', '2011-11-11', '["RPG","Adventure"]', '["Open World","Fantasy","Moddable","First-Person"]', '["Single-player","Achievements","Cloud Saves"]', '/covers/the-elder-scrolls-v-skyrim.hero.jpg', '/covers/the-elder-scrolls-v-skyrim.box.jpg', 94, '$16.49', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'M (Mature 17+)', 'Creation Engine', 'The Elder Scrolls', 94, 'Very Positive', NULL, 34, 230, '["Game of the Year 2011 (Spike Video Game Awards)"]', '["The Special Edition bundles Dawnguard, Hearthfire and Dragonborn.","The guard line about taking an arrow in the knee became an internet meme.","Skyrim has been ported to more console generations than any other Elder Scrolls game."]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('f90131e3-fa68-4241-a621-c0e121d46d52', 'fallout-new-vegas', 'Fallout: New Vegas', 'A courier, a platinum chip and a desert split between rival factions.', 'Set in the Mojave Wasteland four years after Fallout 2, New Vegas puts you in the middle of a war between the NCR, Caesar''s Legion and the reclusive Mr. House. Almost every quest has several solutions, and the ending is assembled from the choices you made.', 'Obsidian Entertainment', 'Bethesda Softworks', '2010-10-19', '["RPG","Shooter"]', '["Post-Apocalyptic","Open World","Choices Matter","Moddable"]', '["Single-player","Achievements"]', '/covers/fallout-new-vegas.hero.jpg', '/covers/fallout-new-vegas.box.jpg', 84, '$2.49', 0, '["PC","PlayStation 3","Xbox 360"]', '["Single-player"]', 'M (Mature 17+)', 'Gamebryo', 'Fallout', 84, 'Overwhelmingly Positive', NULL, 28, 90, '[]', '["Several Obsidian developers had worked on the original Fallout games at Interplay.","It was developed in roughly 18 months while the studio also worked on other projects.","Its four main factions still spark debates about which ending fits best."]'),
('2872efc3-89cb-4493-8d5d-e9372fecea3f', 'mass-effect-legendary-edition', 'Mass Effect Legendary Edition', 'All three Mass Effect games remastered, with most single-player DLC included.', 'Commander Shepard''s trilogy is one long story: choices and relationships carry from game to game, and the Legendary Edition rebuilds the visuals, unifies the character creator and bundles the major expansions.', 'BioWare', 'Electronic Arts', '2021-05-14', '["RPG","Action"]', '["Sci-Fi","Space","Choices Matter","Story Rich"]', '["Single-player","Controller Support","Achievements"]', '/covers/mass-effect-legendary-edition.hero.jpg', '/covers/mass-effect-legendary-edition.box.jpg', 86, '$8.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'M (Mature 17+)', 'Unreal Engine 3', 'Mass Effect', 86, 'Overwhelmingly Positive', NULL, 60, 150, '[]', '["The collection includes over 40 DLC packs, but Mass Effect''s Pinnacle Station is missing because its source data was lost.","It adds a unified character creator that works across all three games.","The original trilogy shipped between 2007 and 2012."]'),
('7b381b54-9cdc-4966-a60a-7198ca984c03', 'god-of-war', 'God of War', 'Kratos raises his son Atreus while carving a path through Norse mythology.', 'A soft reboot that moves Kratos from Greece to Midgard. The journey to scatter his wife''s ashes is told in a single continuous camera shot, with the Leviathan Axe replacing the Blades of Chaos and a boy learning what his father is.', 'Santa Monica Studio', 'Sony Interactive Entertainment', '2018-04-20', '["Action","Adventure"]', '["Norse Mythology","Story Rich","Cinematic","Single Player"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/god-of-war.hero.jpg', '/covers/god-of-war.box.jpg', 94, '$19.99', 0, '["PC","PlayStation 4/5"]', '["Single-player"]', 'M (Mature 17+)', 'In-house (Santa Monica Studio)', 'God of War', 94, 'Very Positive', NULL, 21, 50, '["Game of the Year 2018 (The Game Awards)","Best Game Direction 2018 (The Game Awards)"]', '["The entire game is presented as one continuous shot, with no cuts between scenes.","Christopher Judge won Best Performance at The Game Awards 2018 for voicing Kratos.","The Leviathan Axe returns to Kratos'' hand by design, a mechanic added to keep combat readable."]'),
('bff75448-f143-44ea-8cbe-74d9885bc353', 'uncharted-legacy-of-thieves', 'Uncharted: Legacy of Thieves Collection', 'Uncharted 4 and The Lost Legacy bundled for PS5 and PC.', 'Two treasure hunts from Naughty Dog: Nathan Drake''s last journey in A Thief''s End and Chloe Frazer''s standalone story in The Lost Legacy. The collection adds updated visuals, 120 fps modes and much faster loading.', 'Naughty Dog', 'Sony Interactive Entertainment', '2022-01-28', '["Action","Adventure"]', '["Cinematic","Treasure Hunt","Story Rich","Third-Person"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/uncharted-legacy-of-thieves.hero.jpg', '/covers/uncharted-legacy-of-thieves.box.jpg', 87, '$16.49', 0, '["PC","PlayStation 5"]', '["Single-player"]', 'T (Teen)', 'In-house (Naughty Dog)', 'Uncharted', 87, 'Very Positive', NULL, 16, 35, '[]', '["It is the first Uncharted release to come to PC.","The Lost Legacy started as DLC for Uncharted 4 before growing into a standalone game.","A Thief''s End was the first Uncharted built specifically for the PlayStation 4."]'),
('cac7d094-90ea-4bff-8ad6-8a2dbeb68864', 'marvels-spider-man-remastered', 'Marvel''s Spider-Man Remastered', 'Swing through Manhattan as Peter Parker in Insomniac''s superhero hit.', 'The Remastered release bundles the base game with The City That Never Sleeps, adds a new Peter Parker model and supports ray-traced reflections and 60 fps modes. Combat mixes acrobatic brawling with gadgets and stealth takedowns.', 'Insomniac Games', 'Sony Interactive Entertainment', '2020-11-12', '["Action","Adventure"]', '["Superhero","Open World","Story Rich","Third-Person"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/marvels-spider-man-remastered.hero.jpg', '/covers/marvels-spider-man-remastered.box.jpg', 87, '$23.99', 0, '["PC","PlayStation 4/5"]', '["Single-player"]', 'T (Teen)', 'In-house (Insomniac)', 'Marvel''s Spider-Man', 87, 'Overwhelmingly Positive', NULL, 17, 40, '[]', '["Insomniac built the web-swinging around physics-driven traversal rather than scripted animations.","The Remastered version replaced Peter Parker''s face model, which sparked a long fan debate.","The three DLC chapters follow Black Cat, Hammerhead and Silver Sable."]'),
('d156ced4-a753-4ff6-b5bf-64acc0d276dc', 'monster-hunter-rise', 'Monster Hunter Rise', 'Hunt towering monsters with Wirebug mobility and a Palamute companion.', 'Rise is the portable entry in the Monster Hunter series, built with Capcom''s RE Engine. The Wirebug lets hunters grapple up cliffs and into the air, while the Palamute adds a rideable companion. Sunbreak expands it with Master Rank quests.', 'Capcom', 'Capcom', '2021-03-26', '["Action","RPG"]', '["Hunting","Co-op","Open World","Japanese"]', '["Single-player","Online Co-op","Controller Support","Achievements","Cloud Saves"]', '/covers/monster-hunter-rise.hero.jpg', '/covers/monster-hunter-rise.box.jpg', 88, '$39.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player","Multi-player","Online Co-op"]', 'T (Teen)', 'RE Engine', 'Monster Hunter', 88, 'Very Positive', NULL, 24, 150, '[]', '["The Wirebug shapes combat, traversal and level design across the whole game.","It was the first Monster Hunter built in the RE Engine.","Sunbreak added Master Rank, new locales and the switch skill system."]'),
('c5c7e906-fc5d-4e5f-b231-d3f4b288ada2', 'monster-hunter-wilds', 'Monster Hunter Wilds', 'A seamless open world where monster herds migrate with the weather.', 'The first mainline Monster Hunter built for PS5, Xbox Series and PC, Wilds drops hunters into the Forbidden Lands. Dynamic weather changes the map and the monsters that appear, and the Seikret mount carries you and your weapons.', 'Capcom', 'Capcom', '2025-02-28', '["Action","RPG"]', '["Hunting","Co-op","Open World","Multiplayer"]', '["Single-player","Online Co-op","Controller Support","Achievements","Cloud Saves"]', '/covers/monster-hunter-wilds.hero.jpg', '/covers/monster-hunter-wilds.box.jpg', 88, '$39.99', 0, '["PC","PlayStation 5","Xbox Series X|S"]', '["Single-player","Multi-player","Online Co-op"]', 'T (Teen)', 'RE Engine', 'Monster Hunter', 88, 'Very Positive', NULL, 17, 80, '[]', '["Capcom shipped more than 8 million copies in the first three days.","The game drops the numbered title but continues the mainline series.","Weather cycles change which monsters and resources appear in each region."]'),
('14c54be0-9698-467e-9cac-e29a4cc7cbad', 'resident-evil-village', 'Resident Evil Village', 'Ethan Winters searches a snowbound village for his kidnapped daughter.', 'The eighth main Resident Evil picks up after 7, mixing first-person horror with more action. A cast of lords, led by the towering Lady Dimitrescu, rules the village, and the story ties back to the series'' past.', 'Capcom', 'Capcom', '2021-05-07', '["Horror","Action"]', '["Survival Horror","First-Person","Story Rich","Vampires"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/resident-evil-village.hero.jpg', '/covers/resident-evil-village.box.jpg', 84, '$39.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'M (Mature 17+)', 'RE Engine', 'Resident Evil', 84, 'Overwhelmingly Positive', NULL, 10, 25, '[]', '["Lady Dimitrescu went viral after the first trailer, before the game launched.","It continues the first-person perspective introduced in Resident Evil 7.","A free PS VR2 mode was added in 2023."]'),
('bb32558d-5ee6-4b94-a2a6-2c7f125e6bfa', 'resident-evil-2', 'Resident Evil 2', 'The 1998 survival horror classic rebuilt in the RE Engine.', 'Leon Kennedy and Claire Redfield arrive in Raccoon City as the outbreak begins. The remake swaps fixed cameras for an over-the-shoulder view, keeps the police station''s looping layout and lets players choose which campaign to start.', 'Capcom', 'Capcom', '2019-01-25', '["Horror","Action"]', '["Survival Horror","Zombies","Remake","Third-Person"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/resident-evil-2.hero.jpg', '/covers/resident-evil-2.box.jpg', 91, '$9.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'M (Mature 17+)', 'RE Engine', 'Resident Evil', 91, 'Overwhelmingly Positive', NULL, 9, 25, '[]', '["The remake keeps the original''s A and B scenario structure for both characters.","A free Ghost Survivors mode was added after launch, telling side stories.","The RE Engine''s gore system was built specifically for this remake."]'),
('0345cab9-f6e0-4bda-9472-9bd2bdc0858d', 'street-fighter-6', 'Street Fighter 6', 'Drive Gauges, modern controls and an open-world World Tour mode.', 'The sixth main Street Fighter adds the Drive Gauge, a shared resource for parries, rushes and overdrives. Beyond versus play there is World Tour, a single-player story mode, and Battle Hub, a social lobby.', 'Capcom', 'Capcom', '2023-06-02', '["Fighting","Action"]', '["Arcade","Competitive","Multiplayer","Rollback Netcode"]', '["Single-player","Online PvP","Achievements","Cloud Saves"]', '/covers/street-fighter-6.hero.jpg', '/covers/street-fighter-6.box.jpg', 92, '$39.99', 0, '["PC","PlayStation 4/5","Xbox Series X|S"]', '["Single-player","Multi-player","Online PvP","PvP"]', 'T (Teen)', 'RE Engine', 'Street Fighter', 92, 'Mostly Positive', NULL, 10, 50, '["Best Fighting Game 2023 (The Game Awards)"]', '["Modern controls let newcomers pull off special moves with simple inputs.","World Tour turns the game into a small open-world RPG where you learn moves from masters.","It was the first numbered Street Fighter with rollback netcode at launch."]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('3e37d911-00f8-4b0d-b981-70dbf84e6ec7', 'tekken-8', 'Tekken 8', 'The Mishima saga continues with Heat, a new aggression system.', 'Built in Unreal Engine 5, Tekken 8 follows Jin Kazama against Kazuya in the latest chapter of the Mishima family feud. The Heat system pushes players forward, adding chip damage and new combo routes.', 'Bandai Namco Studios', 'Bandai Namco Entertainment', '2024-01-26', '["Fighting","Action"]', '["Arcade","Competitive","Multiplayer","3D Fighter"]', '["Single-player","Online PvP","Achievements","Cloud Saves"]', '/covers/tekken-8.hero.jpg', '/covers/tekken-8.box.jpg', 90, '$23.99', 0, '["PC","PlayStation 5","Xbox Series X|S"]', '["Single-player","Multi-player","Online PvP","PvP"]', 'T (Teen)', 'Unreal Engine 5', 'Tekken', 90, 'Mixed', NULL, 6, 30, '["Best Fighting Game 2024 (The Game Awards)"]', '["It is the first Tekken built in Unreal Engine 5.","The Heat system is designed to reward attacking instead of turtling.","The roster includes returning fighters and the new fighter Reina."]'),
('9039097f-c6a8-4303-ad44-d09f47d7cbd5', 'persona-3-reload', 'Persona 3 Reload', 'A full remake of the 2006 game that introduced the Persona calendar.', 'By day you attend Gekkoukan High; by night you explore Tartarus with SEES. Reload rebuilds Persona 3 with new visuals, voice acting and rearranged music by Shoji Meguro, while keeping the social links and the Dark Hour.', 'Atlus', 'Sega', '2024-02-02', '["RPG"]', '["JRPG","Turn-Based","High School","Story Rich"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/persona-3-reload.hero.jpg', '/covers/persona-3-reload.box.jpg', 87, '$20.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'M (Mature 17+)', 'Unreal Engine 4', 'Persona', 87, 'Overwhelmingly Positive', NULL, 65, 110, '[]', '["The remake does not include Persona 3 Portable''s female protagonist route.","It adds new link episodes with characters who had no social link in the original.","The soundtrack was rearranged by long-time series composer Shoji Meguro."]'),
('b8f85977-ac7a-4ca1-ba42-19077d0a8fb4', 'metaphor-refantazio', 'Metaphor: ReFantazio', 'Atlus turns its calendar-and-social-link formula toward a fantasy kingdom.', 'A cursed prince, a stolen throne and an election that spans the land: you travel with a fairy companion to win the people''s support. Combat mixes turn-based Archetype jobs with a real-time action layer, and the calendar returns.', 'Atlus', 'Sega', '2024-10-11', '["RPG"]', '["JRPG","Turn-Based","Fantasy","Political"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/metaphor-refantazio.hero.jpg', '/covers/metaphor-refantazio.box.jpg', 94, '$39.99', 0, '["PC","PlayStation 4/5","Xbox Series X|S"]', '["Single-player"]', 'T (Teen)', NULL, 'Metaphor', 94, 'Very Positive', NULL, 60, 110, '["Best RPG 2024 (The Game Awards)","Best Narrative 2024 (The Game Awards)"]', '["It was developed by the team behind Persona 3, 4 and 5.","The Archetype system lets characters swap job-like roles mid-battle.","Its story is built around a royal election rather than a school year."]'),
('424b05fc-6f27-4bbf-b60a-01cd1c92d0b8', 'yakuza-like-a-dragon', 'Yakuza: Like a Dragon', 'Ichiban Kasuga takes over the series and turns it into a turn-based RPG.', 'A fresh lead and a new combat system: Ichiban fights like a Dragon Quest hero, imagining street brawls as turn-based battles. The story moves from Yokohama to Kamurocho as he rebuilds his life after 18 years in prison.', 'Ryu Ga Gotoku Studio', 'Sega', '2020-11-10', '["RPG","Action"]', '["JRPG","Crime","Turn-Based","Story Rich"]', '["Single-player","Controller Support","Achievements"]', '/covers/yakuza-like-a-dragon.hero.jpg', '/covers/yakuza-like-a-dragon.box.jpg', 83, '$6.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'T (Teen)', 'Dragon Engine', 'Yakuza', 83, 'Very Positive', NULL, 46, 100, '[]', '["It replaced the series'' real-time brawling with turn-based party combat.","Ichiban''s love of Dragon Quest is the in-fiction reason battles look like an RPG.","The English release renamed the series Like a Dragon to match the Japanese title."]'),
('c9f6b2c7-f9f0-4941-af6e-cc9454f897d5', 'final-fantasy-vii-remake-intergrade', 'Final Fantasy VII Remake Intergrade', 'The Midgar remake, plus the Yuffie-focused Episode INTERmission.', 'Remake expands the opening hours of Final Fantasy VII into a full game, mixing real-time action with a tactical command menu. Intergrade adds Episode INTERmission, where Yuffie and Sonon infiltrate Shinra.', 'Square Enix', 'Square Enix', '2021-06-10', '["RPG","Action"]', '["JRPG","Remake","Story Rich","Sci-Fi"]', '["Single-player","Achievements","Cloud Saves"]', '/covers/final-fantasy-vii-remake-intergrade.hero.jpg', '/covers/final-fantasy-vii-remake-intergrade.box.jpg', 87, '$7.19', 0, '["PC","PlayStation 5"]', '["Single-player"]', 'T (Teen)', 'Unreal Engine 4', 'Final Fantasy', 87, 'Mostly Positive', NULL, 34, 80, '[]', '["The remake only covers the Midgar section of the 1997 original.","Episode INTERmission stars Yuffie Kisaragi and adds a new combat style.","The original game''s main theme was composed by Nobuo Uematsu."]'),
('3162ff56-208f-4641-bb95-440139841b0c', 'nier-automata', 'NieR: Automata', 'Androids and machines fight a proxy war in a ruined world.', 'PlatinumGames'' action RPG follows 2B, 9S and A2 through a story that replays from different perspectives. Combat blends swordplay with a pod that fires bullet-hell patterns, and the game has 26 endings.', 'PlatinumGames', 'Square Enix', '2017-03-17', '["Action","RPG"]', '["Sci-Fi","Story Rich","Hack and Slash","Multiple Endings"]', '["Single-player","Achievements","Cloud Saves"]', '/covers/nier-automata.hero.jpg', '/covers/nier-automata.box.jpg', 84, '$15.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'M (Mature 17+)', 'In-house (PlatinumGames)', 'NieR', 84, 'Mostly Positive', NULL, 21, 60, '["Best Score/Music 2017 (The Game Awards)"]', '["The game has 26 endings, many of them jokes triggered by odd actions.","Director Yoko Taro is known for wearing a mask during public appearances.","Its soundtrack blends vocals with invented languages."]'),
('ee115c3e-aed8-4fe7-bc41-8d4ea396e999', 'dragon-quest-xi-s', 'Dragon Quest XI S: Echoes of an Elusive Age', 'A classic turn-based JRPG with orchestral music and a 2D mode.', 'The Luminary is hunted across Erdrea while gathering a party of misfits. The Definitive Edition adds orchestral music, extra character stories and the option to play the whole game in 2D.', 'Square Enix', 'Square Enix', '2019-09-27', '["RPG","Adventure"]', '["JRPG","Turn-Based","Fantasy","Classic"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/dragon-quest-xi-s.hero.jpg', '/covers/dragon-quest-xi-s.box.jpg', 85, '$19.99', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player"]', 'T (Teen)', 'Unreal Engine 4', 'Dragon Quest', 85, 'Very Positive', NULL, 58, 120, '[]', '["The Definitive Edition''s 2D mode recreates the look of older Dragon Quest games.","Series creator Yuji Horii and composer Koichi Sugiyama worked on the game.","It was the first mainline Dragon Quest to release on Xbox in the West."]'),
('893b0535-031c-4698-9bc1-2fa64119144d', 'ori-and-the-will-of-the-wisps', 'Ori and the Will of the Wisps', 'A hand-painted metroidvania about a spirit guarding a dying forest.', 'Moon Studios follows Ori into Niwen after a storm separates him from Ku. The sequel adds melee combat, a hub with upgrades and tighter platforming, all set to a score by Gareth Coker.', 'Moon Studios', 'Xbox Game Studios', '2020-03-11', '["Platformer","Adventure"]', '["Metroidvania","Beautiful","Emotional","Soundtrack"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/ori-and-the-will-of-the-wisps.hero.jpg', '/covers/ori-and-the-will-of-the-wisps.box.jpg', 90, '$7.49', 0, '["PC","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'E (Everyone)', 'Unity', 'Ori', 90, 'Very Positive', NULL, 13, 25, '["Best Music 2020 (The Game Awards)"]', '["Moon Studios is a fully remote team spread across several countries.","The game runs at 120 fps on Xbox Series X.","Its soundtrack was composed by Gareth Coker and recorded with live musicians."]'),
('399081ea-2fcf-4e89-a318-38b091dd577f', 'assassins-creed-valhalla', 'Assassin''s Creed Valhalla', 'Lead a Viking clan from Norway to England and build a new home.', 'Eivor and the Raven Clan cross the North Sea to settle in England, where every shire is held by a different lord. Raids, a settlement to upgrade and the series'' modern-day arc run alongside a story about loyalty and conquest.', 'Ubisoft Montreal', 'Ubisoft', '2020-11-10', '["Action","RPG"]', '["Open World","Vikings","Stealth","Historical"]', '["Single-player","Achievements"]', '/covers/assassins-creed-valhalla.hero.jpg', '/covers/assassins-creed-valhalla.box.jpg', 83, '$14.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'M (Mature 17+)', 'AnvilNext 2.0', 'Assassin''s Creed', 83, 'Mixed', NULL, 61, 110, '[]', '["Eivor can be played as either a male or female character, and the game treats both as the same person.","The settlement of Ravensthorpe grows as you recruit new residents and build facilities.","It was the first Assassin''s Creed built for the PlayStation 5 and Xbox Series consoles."]'),
('73e9f1e0-3843-4f53-b4cb-3b9d1bad775e', 'far-cry-6', 'Far Cry 6', 'Join a guerrilla uprising against a dictator on the island of Yara.', 'Yara is a Caribbean nation frozen in time by an embargo, and its president Antón Castillo intends to keep it that way. You play Dani Rojas, a local who joins the resistance and works across the island to weaken the regime.', 'Ubisoft Toronto', 'Ubisoft', '2021-10-07', '["Shooter","Action"]', '["Open World","First-Person","Co-op","Revolution"]', '["Single-player","Online Co-op","Achievements"]', '/covers/far-cry-6.hero.jpg', '/covers/far-cry-6.box.jpg', 74, '$14.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player","Multi-player","Online Co-op"]', 'M (Mature 17+)', 'Dunia Engine', 'Far Cry', 74, 'Mixed', NULL, 24, 60, '[]', '["Giancarlo Esposito plays the dictator Antón Castillo and his son Diego.","Yara is a fictional island inspired by Cuba, and the game keeps Spanish voice acting throughout.","The whole campaign can be played in two-player co-op."]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('0103ee84-8e56-403a-a3d5-d8d2dc14362f', 'tom-clancys-rainbow-six-siege', 'Tom Clancy''s Rainbow Six Siege', 'Five-versus-five tactical matches built around breaching and defending rooms.', 'Each round is a small siege: attackers breach walls, floors and windows while defenders fortify the objective. Operators bring one gadget each, so team composition matters as much as aim.', 'Ubisoft Montreal', 'Ubisoft', '2015-12-01', '["Shooter","Strategy"]', '["Tactical","Competitive","Multiplayer","Esports"]', '["Single-player","Online Co-op","Online PvP","Controller Support"]', '/covers/tom-clancys-rainbow-six-siege.hero.jpg', '/covers/tom-clancys-rainbow-six-siege.box.jpg', 79, 'Free', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player","Multi-player","Online Co-op","Online PvP","PvP"]', 'M (Mature 17+)', 'AnvilNext 2.0', 'Rainbow Six', 79, 'Mostly Positive', NULL, NULL, NULL, '[]', '["It launched in 2015 as a slower, more destructive alternative to arena shooters.","Almost every wall and floor can be destroyed, which reshapes the map each round.","The game has been supported with seasonal operators for years rather than sequels."]'),
('ec0cf344-71c3-42ca-aa7b-f304b4b7b109', 'destiny-2', 'Destiny 2', 'A shared-world shooter about Guardians, loot and the last city on Earth.', 'Destiny 2 mixes precise gunplay with loot rolls and raids built for six players. The free New Light entry covers the opening campaigns, while annual expansions add new destinations, subclasses and story arcs.', 'Bungie', 'Bungie', '2017-10-24', '["Shooter","RPG"]', '["Sci-Fi","Looter Shooter","Co-op","Multiplayer"]', '["Single-player","Online Co-op","Online PvP","Achievements"]', '/covers/destiny-2.hero.jpg', '/covers/destiny-2.box.jpg', 85, 'Free', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player","Multi-player","Online Co-op","Online PvP","PvP"]', 'T (Teen)', 'Tiger Engine', 'Destiny', 85, 'Very Positive', NULL, NULL, NULL, '[]', '["Bungie moved the game from Battle.net to Steam in 2019 and made the base game free to play.","Raids are designed for six coordinated players and have no matchmaking.","Destiny 2 continued the story of the 2014 original rather than starting over."]'),
('521a9ced-b8ff-48e4-9692-6dcaa062477e', 'warframe', 'Warframe', 'Free-to-play space ninjas with a huge arsenal of frames and weapons.', 'Tenno wake from cryosleep and fight the Grineer and Corpus across the solar system. Each Warframe has its own abilities, and missions range from quick exterminations to open-world hunts.', 'Digital Extremes', 'Digital Extremes', '2013-03-25', '["Action","RPG"]', '["Free to Play","Sci-Fi","Co-op","Looter Shooter"]', '["Single-player","Online Co-op","Controller Support","Achievements"]', '/covers/warframe.hero.jpg', '/covers/warframe.box.jpg', 69, 'Free', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player","Multi-player","Online Co-op"]', 'M (Mature 17+)', 'Evolution Engine', 'N/A', 69, 'Very Positive', NULL, NULL, NULL, '[]', '["It began as a free-to-play follow-up to Digital Extremes'' Dark Sector.","New Warframes are usually earned by farming parts rather than bought outright.","The game has run for more than a decade with regular free updates."]'),
('b180ca7e-1fea-4873-90dc-2c3326f0f4b1', 'path-of-exile', 'Path of Exile', 'A free-to-play action RPG built around an enormous passive skill tree.', 'Exiles are banished to Wraeclast and build characters from gems, gear and a passive tree with over a thousand nodes. Seasonal leagues reset the economy and add new mechanics every few months.', 'Grinding Gear Games', 'Grinding Gear Games', '2013-10-23', '["RPG","Action"]', '["Free to Play","ARPG","Dark Fantasy","Loot"]', '["Single-player","Online Co-op","Online PvP","Controller Support","Achievements"]', '/covers/path-of-exile.hero.jpg', '/covers/path-of-exile.box.jpg', 86, 'Free', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player","Multi-player","Online Co-op","Online PvP","PvP"]', 'M (Mature 17+)', 'In-house (Grinding Gear Games)', 'N/A', 86, 'Very Positive', NULL, NULL, NULL, '[]', '["The passive skill tree is shared by every class; only the starting point changes.","Skill gems are items, so builds are assembled from gear rather than fixed classes.","Leagues typically last around three months before the next one starts."]'),
('6f8ec587-5509-4167-90b9-78f4159f7b4f', 'final-fantasy-xiv-online', 'Final Fantasy XIV Online', 'A subscription MMORPG that rebuilt itself into one of the genre''s best stories.', 'After the original 2010 release was shut down, A Realm Reborn relaunched the game and turned it around. The story now spans several expansions, from Heavensward to Dawntrail, with a free trial covering the early ones.', 'Square Enix', 'Square Enix', '2013-08-27', '["RPG","Adventure"]', '["MMORPG","Fantasy","Story Rich","Subscription"]', '["Single-player","Online Co-op","Online PvP"]', '/covers/final-fantasy-xiv-online.hero.jpg', '/covers/final-fantasy-xiv-online.box.jpg', 83, '$19.99', 0, '["PC","PlayStation 4/5","macOS"]', '["Single-player","Multi-player","Online Co-op","Online PvP","PvP"]', 'T (Teen)', 'In-house (Square Enix)', 'Final Fantasy', 83, 'Very Positive', NULL, NULL, NULL, '[]', '["The original 1.0 version ended with a server-wide apocalypse event before relaunching.","Producer Naoki Yoshida took over the project and later led the relaunch.","The free trial lets players reach level 70 without a subscription."]'),
('87d9e710-772d-4571-afa6-f34c3a6d22fb', 'total-war-three-kingdoms', 'Total War: Three Kingdoms', 'Total War moves to ancient China with duels, diplomacy and warlord factions.', 'The campaign covers the end of the Han dynasty and the wars that followed. Armies fight in real time while the map layer adds character relationships, spies and a detailed diplomacy system.', 'Creative Assembly', 'Sega', '2019-05-23', '["Strategy"]', '["Strategy","Historical","Turn-Based","Real-Time Tactics"]', '["Single-player","Online Co-op","Online PvP","Achievements","Cloud Saves"]', '/covers/total-war-three-kingdoms.hero.jpg', '/covers/total-war-three-kingdoms.box.jpg', 85, '$11.99', 0, '["PC"]', '["Single-player","Multi-player","Online Co-op","Online PvP","PvP"]', 'T (Teen)', 'In-house (Creative Assembly)', 'Total War', 85, 'Mostly Positive', NULL, 41, 150, '[]', '["It offers a Romance mode with duels and a Records mode closer to the historical source.","Character relationships affect diplomacy, recruitment and succession.","It was the first Total War set in China."]'),
('cb67098b-667e-4eaf-987f-c166a85053e4', 'crusader-kings-iii', 'Crusader Kings III', 'A medieval dynasty simulator where inheritance is the real enemy.', 'You play a ruler rather than a nation, and the game continues through heirs. Marriages, claims, schemes and the occasional murder keep a dynasty alive across centuries of map-painting.', 'Paradox Development Studio', 'Paradox Interactive', '2020-09-01', '["Strategy","RPG"]', '["Grand Strategy","Medieval","Dynasty","Sandbox"]', '["Single-player","Online PvP","Achievements","Cloud Saves"]', '/covers/crusader-kings-iii.hero.jpg', '/covers/crusader-kings-iii.box.jpg', 91, '$14.99', 0, '["PC","PlayStation 5","Xbox Series X|S"]', '["Single-player","Multi-player","Online PvP","PvP"]', 'T (Teen)', 'Clausewitz Engine', 'Crusader Kings', 91, 'Very Positive', NULL, 60, 150, '[]', '["There is no win condition; the game is a sandbox that ends when your dynasty does.","Characters have personalities and secrets that shape how they behave.","The series became known online for stories about horses inheriting titles."]'),
('23f44978-5193-4d54-9124-3f6dd06933ca', 'stellaris', 'Stellaris', 'A grand strategy game about taking a custom species to the stars.', 'Stellaris starts with a freshly designed species and a single planet. From there it is exploration, diplomacy, research and war across a procedurally generated galaxy that includes fallen empires and crises.', 'Paradox Development Studio', 'Paradox Interactive', '2016-05-09', '["Strategy"]', '["Grand Strategy","Sci-Fi","Space","Sandbox"]', '["Single-player","Online Co-op","Online PvP","Achievements","Cloud Saves"]', '/covers/stellaris.hero.jpg', '/covers/stellaris.box.jpg', 73, '$14.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player","Multi-player","Online Co-op","Online PvP","PvP"]', 'T (Teen)', 'Clausewitz Engine', 'N/A', 73, 'Mixed', NULL, 30, 100, '[]', '["Players design their own species, government and starting traits.","The galaxy is procedurally generated, including other empires and crises.","Paradox has overhauled major systems such as planets and population several times."]'),
('cb019ba4-a760-4bc4-835f-6da7f8d42ce0', 'age-of-empires-iv', 'Age of Empires IV', 'The classic RTS returns with asymmetric civilizations and campaign documentaries.', 'Eight civilizations, each with distinct units and mechanics, fight across historical campaigns and skirmish maps. The campaigns use filmed segments and archival material between missions.', 'Relic Entertainment', 'Xbox Game Studios', '2021-10-28', '["Strategy"]', '["RTS","Historical","Base Building","Multiplayer"]', '["Single-player","Online Co-op","Online PvP","Controller Support","Achievements"]', '/covers/age-of-empires-iv.hero.jpg', '/covers/age-of-empires-iv.box.jpg', 81, '$13.99', 0, '["PC","Xbox One/Series X|S"]', '["Single-player","Multi-player","Online Co-op","Online PvP","PvP"]', 'T (Teen)', 'Essence Engine', 'Age of Empires', 81, 'Mostly Positive', NULL, 25, 65, '[]', '["Relic Entertainment developed it with World''s Edge, the Age of Empires studio.","It was the first new numbered entry in the series since 2005.","Each civilization has its own way of advancing through the ages."]'),
('41b764ac-222b-41ea-94ce-9b8e78e5a9d7', 'halo-infinite', 'Halo Infinite', 'Master Chief returns on a ringworld, with free-to-play multiplayer.', 'The campaign sends Chief to Zeta Halo to fight the Banished, with a grappleshot that opens up traversal and combat. Multiplayer is free to play and has its own seasonal progression.', '343 Industries', 'Xbox Game Studios', '2021-12-08', '["Shooter","Action"]', '["Sci-Fi","First-Person","Free to Play","Multiplayer"]', '["Online PvP","Controller Support","Achievements","Cloud Saves"]', '/covers/halo-infinite.hero.jpg', '/covers/halo-infinite.box.jpg', 87, 'Free', 0, '["PC","Xbox One/Series X|S"]', '["Multi-player","Online PvP","PvP"]', 'T (Teen)', 'Slipspace Engine', 'Halo', 87, 'Mixed', NULL, 12, 30, '[]', '["Multiplayer launched separately and free to play, while the campaign is sold on its own.","The grappleshot was added to make the open ring sections more vertical.","It was built on a new engine, Slipspace, made for the game."]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('315b3526-cd79-4a03-a8d5-8835dc1591f5', 'halo-the-master-chief-collection', 'Halo: The Master Chief Collection', 'Six Halo campaigns and their multiplayer suites in one package.', 'The collection gathers Combat Evolved, Halo 2, Halo 3, ODST, Reach and Halo 4, each with its campaign and multiplayer maps. A single launcher and match composer tie them together.', '343 Industries', 'Xbox Game Studios', '2014-11-11', '["Shooter","Action"]', '["Sci-Fi","First-Person","Co-op","Classic"]', '["Single-player","Online Co-op","Online PvP","Controller Support","Achievements"]', '/covers/halo-the-master-chief-collection.hero.jpg', '/covers/halo-the-master-chief-collection.box.jpg', 85, '$9.99', 0, '["PC","Xbox One/Series X|S"]', '["Single-player","Multi-player","Online Co-op","Online PvP","PvP"]', 'M (Mature 17+)', 'In-house (343 Industries)', 'Halo', 85, 'Very Positive', NULL, 60, 250, '[]', '["Halo 2 Anniversary includes remastered cutscenes by Blur Studio.","The PC versions arrived years after the Xbox One release, one game at a time.","The collection lets players mix campaign and multiplayer playlists across games."]'),
('dc9bb5af-74ce-4a0b-8f63-724e20135524', 'a-way-out', 'A Way Out', 'A co-op prison break told entirely through two players.', 'Leo and Vincent meet in prison and plan an escape together. The game is built for exactly two players, splits the screen and frequently hands each player different tasks in the same scene.', 'Hazelight Studios', 'Electronic Arts', '2018-03-23', '["Adventure","Action"]', '["Co-op","Story Rich","Cinematic","Split Screen"]', '["Online Co-op","Local Co-op","Controller Support","Achievements","Remote Play"]', '/covers/a-way-out.hero.jpg', '/covers/a-way-out.box.jpg', 78, '$5.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Multi-player","Online Co-op","Local Co-op"]', 'M (Mature 17+)', 'Unreal Engine 4', 'N/A', 78, 'Very Positive', NULL, 6, 8, '[]', '["It can only be played with two people, locally or online.","The screen often splits unevenly to show both characters during the same moment.","Hazelight followed it with It Takes Two, built on the same co-op philosophy."]'),
('fe2d7d41-6e0c-4416-b77e-c22f61f76b23', 'overcooked-2', 'Overcooked! 2', 'Co-op cooking chaos on kitchens that keep falling apart.', 'Orders pile up while the kitchen splits, moves or catches fire. Up to four players chop, cook and plate together, and the sequel adds online play and throwing ingredients across gaps.', 'Ghost Town Games', 'Team17', '2018-08-07', '["Simulation","Adventure"]', '["Co-op","Party","Funny","Local Multiplayer"]', '["Single-player","Online Co-op","Local Co-op","Online PvP","Controller Support","Achievements"]', '/covers/overcooked-2.hero.jpg', '/covers/overcooked-2.box.jpg', 81, '$8.24', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player","Multi-player","Online Co-op","Local Co-op","Online PvP","PvP"]', 'E (Everyone)', 'Unity', 'Overcooked', 81, 'Very Positive', NULL, 8, 20, '[]', '["The original Overcooked was local-only; this sequel added online co-op.","Players can throw raw ingredients to each other across obstacles.","Levels are timed, and stars are awarded based on how many orders are filled."]'),
('23c5920c-8cf9-4abe-aa68-bef179f08192', 'human-fall-flat', 'Human: Fall Flat', 'A wobbly physics puzzle game about floppy people and teamwork.', 'Bob has no special powers beyond arms that flail, and the levels are built around that. Climb, swing and shove friends through dreamlike maps, with workshop support for community levels.', 'No Brakes Games', 'Curve Games', '2016-07-22', '["Platformer","Adventure"]', '["Physics","Co-op","Puzzle","Funny"]', '["Single-player","Local Co-op","Online PvP","Controller Support","Achievements","Cloud Saves"]', '/covers/human-fall-flat.hero.jpg', '/covers/human-fall-flat.box.jpg', 70, '$19.99', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player","Multi-player","Local Co-op","Online PvP","PvP"]', 'E10+ (Everyone 10+)', 'Unity', 'N/A', 70, 'Overwhelmingly Positive', NULL, 5, 12, '[]', '["The character''s loose, deliberately clumsy movement is the whole design.","Steam Workshop support lets players publish and play custom levels.","It supports online co-op for up to eight players."]'),
('226e6c91-2ff8-4dbb-993a-25d064ae02c1', 'sons-of-the-forest', 'Sons of the Forest', 'Survive a cannibal island while searching for a missing billionaire.', 'A rescue mission turns into a fight to build shelter, find food and stay alive underground. AI companions Kelvin and Virginia help, and the island hides caves and a story that connects to The Forest.', 'Endnight Games', 'Newnight', '2024-02-22', '["Adventure","Horror"]', '["Survival","Horror","Crafting","Co-op"]', '["Single-player","Online Co-op","Controller Support","Achievements","Cloud Saves"]', '/covers/sons-of-the-forest.hero.jpg', '/covers/sons-of-the-forest.box.jpg', 78, '$29.99', 0, '["PC"]', '["Single-player","Multi-player","Online Co-op"]', 'M (Mature 17+)', 'Unity', 'The Forest', 78, 'Very Positive', NULL, 20, 50, '[]', '["It launched in early access in 2023 and reached 1.0 the following year.","Kelvin is deaf and follows written notes instead of spoken orders.","It is a sequel to The Forest, with returning story threads."]'),
('d3079cbf-7ac3-494e-a1cd-0447941a3fb5', 'phasmophobia', 'Phasmophobia', 'Four-player ghost hunting with tools, evidence and a van to hide in.', 'Teams enter haunted locations with EMF readers, cameras and spirit boxes to identify the ghost. The ghost reacts to voice chat, and the van outside is the only safe place to review evidence.', 'Kinetic Games', 'Kinetic Games', '2020-09-18', '["Horror","Simulation"]', '["Horror","Co-op","Investigation","VR"]', '["Single-player","Online Co-op","Controller Support","Achievements","Cloud Saves"]', '/covers/phasmophobia.hero.jpg', '/covers/phasmophobia.box.jpg', NULL, '$19.99', 0, '["PC","PlayStation 5","Xbox Series X|S"]', '["Single-player","Multi-player","Online Co-op"]', 'T (Teen)', 'Unity', 'N/A', NULL, 'Very Positive', NULL, NULL, NULL, '[]', '["It started as a small indie early-access release and became a co-op horror staple.","Ghosts can hear players through voice chat and react to their names.","Console versions arrived in 2024 with optional VR support."]'),
('baaff2af-6c72-48ad-8cde-6f107fc4bcd4', 'lethal-company', 'Lethal Company', 'Scavenge abandoned moons for a company that does not care if you live.', 'Up to four employees land on a moon, collect scrap before dark and try to meet a quota. Proximity chat means every scream is heard by the team, and the monsters are mostly avoided rather than fought.', 'Zeekerss', 'Zeekerss', '2023-10-23', '["Horror","Adventure"]', '["Co-op","Horror","Proximity Chat","Roguelike"]', '["Single-player","Online Co-op"]', '/covers/lethal-company.hero.jpg', '/covers/lethal-company.box.jpg', NULL, '$9.99', 0, '["PC"]', '["Single-player","Multi-player","Online Co-op"]', NULL, 'Unity', 'N/A', NULL, 'Very Positive', NULL, NULL, NULL, '[]', '["It was made largely by one developer, Zeekerss.","Proximity voice chat is central: teammates only hear you when you are close.","The quota system means each run ends with a landing that may be your last."]'),
('3f64620e-eaf8-4ebd-9bea-9389d4326fc6', 'helldivers-2', 'Helldivers 2', 'Four-player co-op war against bugs and robots, with friendly fire always on.', 'Helldivers drop onto planets in a shared galactic war and call in stratagems from orbit. The shift to third person keeps the friendly fire, the satirical propaganda and the very short life expectancy.', 'Arrowhead Game Studios', 'Sony Interactive Entertainment', '2024-02-08', '["Shooter","Action"]', '["Co-op","Third-Person","Sci-Fi","Satire"]', '["Online Co-op","Achievements"]', '/covers/helldivers-2.hero.jpg', '/covers/helldivers-2.box.jpg', 82, '$29.99', 0, '["PC","PlayStation 5"]', '["Multi-player","Online Co-op"]', 'M (Mature 17+)', 'Autodesk Stingray', 'Helldivers', 82, 'Mostly Negative', NULL, 20, 60, '["Best Multiplayer 2024 (The Game Awards)"]', '["The first Helldivers was a top-down twin-stick shooter; the sequel moved to third person.","Friendly fire is always enabled, including from orbital strikes.","The community-wide Galactic War advances or retreats based on player actions."]'),
('c625f8f2-0992-40e0-b268-a58c68b0e1b4', 'palworld', 'Palworld', 'Catch creatures, put them to work and build a base in an open world.', 'Pals can fight, mine, craft and staff production lines, which makes the base-building as important as the combat. The game mixes survival crafting with creature collection and optional four-player co-op.', 'Pocketpair', 'Pocketpair', '2024-01-19', '["Adventure","RPG"]', '["Open World","Survival","Crafting","Creature Collector"]', '["Single-player","Online Co-op","Controller Support","Achievements","Cloud Saves"]', '/covers/palworld.hero.jpg', '/covers/palworld.box.jpg', 71, '$29.99', 0, '["PC","Xbox One/Series X|S"]', '["Single-player","Multi-player","Online Co-op"]', 'T (Teen)', 'Unreal Engine 5', 'N/A', 71, 'Overwhelmingly Positive', NULL, 30, 80, '[]', '["It became famous online for the contrast between cute Pals and factory work.","Pocketpair had previously made the crafting game Craftopia.","It entered early access in January 2024 and sold millions of copies in its first week."]'),
('0482be71-4653-4a12-b0e2-6bedfea1296a', 'divinity-original-sin-2', 'Divinity: Original Sin 2', 'A turn-based RPG where elemental surfaces and choices both matter.', 'Six origin characters each carry their own story into a prison colony and beyond. Combat uses action points, elemental combinations and verticality, and almost every quest has more than one solution.', 'Larian Studios', 'Larian Studios', '2017-09-14', '["RPG","Strategy"]', '["Turn-Based","Fantasy","Co-op","Choices Matter"]', '["Single-player","Online Co-op","Local Co-op","Online PvP","Controller Support","Achievements"]', '/covers/divinity-original-sin-2.hero.jpg', '/covers/divinity-original-sin-2.box.jpg', 93, '$11.24', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player","Multi-player","Online Co-op","Local Co-op","Online PvP","PvP"]', 'M (Mature 17+)', 'Divinity Engine 3', 'Divinity', 93, 'Very Positive', NULL, 60, 120, '[]', '["It was funded through Kickstarter and grew substantially from the pitch.","Larian later used the experience to build Baldur''s Gate 3.","Up to four players can play the campaign together, including in split screen."]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('36cd9e89-1c39-4f82-9279-7e2df300de19', 'final-fantasy-xvi', 'Final Fantasy XVI', 'A darker Final Fantasy with real-time combat and colossal Eikon battles.', 'Clive Rosfield''s life is shaped by the fall of his kingdom and the power of the Eikons. Combat is fully action-based, with ability loadouts and large set-piece fights between summons.', 'Creative Business Unit III', 'Square Enix', '2023-06-22', '["RPG","Action"]', '["Fantasy","Action","Story Rich","Cinematic"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/final-fantasy-xvi.hero.jpg', '/covers/final-fantasy-xvi.box.jpg', 87, '$19.99', 0, '["PC","PlayStation 5"]', '["Single-player"]', 'M (Mature 17+)', 'In-house (Square Enix)', 'Final Fantasy', 87, 'Mostly Positive', NULL, 36, 80, '["Best Score/Music 2023 (The Game Awards)"]', '["Combat designer Ryota Suzuki previously worked on Devil May Cry and Dragon''s Dogma.","It was the first mainline Final Fantasy to receive an M rating from the ESRB.","The PC version arrived in 2024 with both expansion chapters."]'),
('065a05ba-a9af-4958-a768-10b0caf673b1', 'horizon-forbidden-west', 'Horizon Forbidden West', 'Aloy travels west to stop a blight and find the source of a dying world.', 'The sequel expands the machine roster and adds underwater exploration, gliding and a much larger map. Aloy''s focus now scans for weak points, and the story pushes further into the old world''s mistakes.', 'Guerrilla Games', 'Sony Interactive Entertainment', '2022-02-18', '["Action","RPG"]', '["Open World","Sci-Fi","Post-Apocalyptic","Story Rich"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/horizon-forbidden-west.hero.jpg', '/covers/horizon-forbidden-west.box.jpg', 88, '$29.99', 0, '["PC","PlayStation 4/5"]', '["Single-player"]', 'T (Teen)', 'Decima Engine', 'Horizon', 88, 'Very Positive', NULL, 30, 80, '[]', '["The Burning Shores expansion was released for PlayStation 5 only.","Underwater sections let Aloy swim and hide from machines for the first time.","The PC port arrived in 2024, two years after the console release."]'),
('5a68f7de-b86c-4272-be42-0a6e8975c81f', 'watch-dogs-legion', 'Watch Dogs: Legion', 'Recruit anyone in a near-future London to rebuild DedSec.', 'After a bombing is blamed on hackers, DedSec is outlawed and London falls under private surveillance. The twist is that every NPC can be recruited, each with their own job, perks and access.', 'Ubisoft Toronto', 'Ubisoft', '2020-10-29', '["Action","Adventure"]', '["Open World","Hacking","Stealth","Near Future"]', '["Single-player","Online Co-op","Online PvP","Achievements"]', '/covers/watch-dogs-legion.hero.jpg', '/covers/watch-dogs-legion.box.jpg', 72, '$8.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player","Multi-player","Online Co-op","Online PvP","PvP"]', 'M (Mature 17+)', 'Disrupt Engine', 'Watch Dogs', 72, 'Mixed', NULL, 18, 44, '[]', '["Any character in the open world can be recruited, including enemies and pensioners.","An optional permadeath mode makes recruited operatives permanently lost when they die.","The map covers a compressed version of central London, including Camden and Westminster."]'),
('d65ec827-d8eb-4be0-b2b7-b9e137999d51', 'microsoft-flight-simulator', 'Microsoft Flight Simulator', 'Fly a detailed simulation of the whole planet with live weather.', 'Satellite imagery, photogrammetry and real-time weather are streamed to recreate the Earth at a scale where you can land anywhere. Aircraft range from light props to airliners, with detailed cockpits and systems.', 'Asobo Studio', 'Xbox Game Studios', '2020-08-18', '["Simulation"]', '["Simulation","Realistic","Open World","Flight"]', '["Single-player","Controller Support","Achievements"]', '/covers/microsoft-flight-simulator.hero.jpg', '/covers/microsoft-flight-simulator.box.jpg', 91, '$20.99', 0, '["PC","Xbox Series X|S"]', '["Single-player","Multi-player"]', 'E (Everyone)', 'In-house (Asobo Studio)', 'Microsoft Flight Simulator', 91, 'Very Positive', NULL, NULL, NULL, '[]', '["The world is streamed from Bing Maps data and can be flown without loading screens.","Live weather and air traffic can be enabled to match the real world.","It was the first new entry in the series since Flight Simulator X in 2006."]'),
('9bcb80f0-eb1d-44e8-b5f9-b9dfce330331', 'ratchet-and-clank-rift-apart', 'Ratchet & Clank: Rift Apart', 'A dimension-hopping adventure built around instant world switching.', 'Dr. Nefarious tears holes between dimensions and separates Ratchet and Clank. The game swaps entire levels in a blink, and Rivet, a counterpart from another dimension, joins the fight.', 'Insomniac Games', 'Sony Interactive Entertainment', '2021-06-11', '["Platformer","Action"]', '["Platformer","Sci-Fi","Third-Person","Family Friendly"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/ratchet-and-clank-rift-apart.hero.jpg', '/covers/ratchet-and-clank-rift-apart.box.jpg', 88, '$23.99', 0, '["PC","PlayStation 5"]', '["Single-player"]', 'E10+ (Everyone 10+)', 'In-house (Insomniac Games)', 'Ratchet & Clank', 88, 'Very Positive', NULL, 11, 25, '[]', '["The rift mechanic loads a new area almost instantly, a showcase for the PS5 SSD.","Rivet is a new playable Lombax from an alternate dimension.","It was the first Ratchet & Clank game built for PlayStation 5."]'),
('561a2d57-5462-4cfc-9d1f-a0a7ccb0e854', 'returnal', 'Returnal', 'A bullet-hell roguelike about a pilot trapped on a hostile planet.', 'Selene crash-lands on Atropos and dies, then wakes at the crash site again. Each run rebuilds the planet, and the story unfolds through the fragments she finds between deaths.', 'Housemarque', 'Sony Interactive Entertainment', '2021-04-30', '["Shooter","Action"]', '["Roguelike","Bullet Hell","Sci-Fi","Third-Person"]', '["Single-player","Online Co-op","Controller Support","Achievements","Cloud Saves"]', '/covers/returnal.hero.jpg', '/covers/returnal.box.jpg', 86, '$19.79', 0, '["PC","PlayStation 5"]', '["Single-player","Multi-player","Online Co-op"]', 'M (Mature 17+)', 'Unreal Engine 4', 'N/A', 86, 'Mostly Positive', NULL, 20, 60, '[]', '["Housemarque built its reputation on arcade shooters like Resogun and Nex Machina.","The DualSense triggers switch between aiming and alt-fire modes.","The PC version added co-op and ultrawide support in 2023."]'),
('1f4a3558-d6f9-49bc-85be-766396869a88', 'days-gone', 'Days Gone', 'A biker survives a zombie outbreak in the American Northwest.', 'Deacon St. John searches for his wife while running jobs for camps in Oregon. The open world is built around a motorcycle that needs fuel, and Freaker hordes can number in the hundreds.', 'Bend Studio', 'Sony Interactive Entertainment', '2019-04-26', '["Action","Horror"]', '["Open World","Zombies","Survival","Story Rich"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/days-gone.hero.jpg', '/covers/days-gone.box.jpg', 71, '$13.19', 0, '["PC","PlayStation 4"]', '["Single-player"]', 'M (Mature 17+)', 'Unreal Engine 4', 'N/A', 71, 'Very Positive', NULL, 36, 70, '[]', '["The horde system can send hundreds of Freakers after the player at once.","Bend Studio had previously made the Syphon Filter and Resistance: Retribution games.","It came to PC in 2021 with support for ultrawide monitors."]'),
('f52beffb-080c-4d31-9d82-ebac951516a7', 'marvels-spider-man-miles-morales', 'Marvel''s Spider-Man: Miles Morales', 'Miles takes over the mask while Harlem becomes his neighbourhood.', 'A shorter, tighter follow-up to the 2018 game. Miles has venom powers and camouflage, and the story is about him deciding what kind of hero he wants to be.', 'Insomniac Games', 'Sony Interactive Entertainment', '2020-11-12', '["Action","Adventure"]', '["Superhero","Open World","Story Rich","Third-Person"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/marvels-spider-man-miles-morales.hero.jpg', '/covers/marvels-spider-man-miles-morales.box.jpg', 85, '$19.99', 0, '["PC","PlayStation 4/5"]', '["Single-player"]', 'T (Teen)', 'In-house (Insomniac Games)', 'Marvel''s Spider-Man', 85, 'Very Positive', NULL, 8, 18, '[]', '["It began as a smaller project and grew into a standalone game.","Miles'' venom blast and camouflage change how stealth and combat work.","The PC release arrived in 2022 with ray-traced reflections."]'),
('c4de2724-3781-4f92-80e3-973b96b28ec3', 'shadow-of-the-tomb-raider', 'Shadow of the Tomb Raider', 'Lara races a paramilitary group to a Mayan city hidden in the jungle.', 'The final chapter of the reboot trilogy takes Lara to Mexico and Peru. Stealth, underwater traversal and a hub city in Paititi make it the most open of the three.', 'Eidos-Montréal', 'Square Enix', '2018-09-14', '["Action","Adventure"]', '["Adventure","Exploration","Stealth","Cinematic"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/shadow-of-the-tomb-raider.hero.jpg', '/covers/shadow-of-the-tomb-raider.box.jpg', 78, '$39.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player"]', 'M (Mature 17+)', 'Foundation Engine', 'Tomb Raider', 78, 'Mostly Positive', NULL, 13, 30, '[]', '["It is the third game in the reboot trilogy that started with Tomb Raider in 2013.","Paititi is the largest hub area in the trilogy.","Lara can dive and hide underwater, a new system for the series."]'),
('5392861c-1215-4459-a249-95a54a8384c2', 'batman-arkham-knight', 'Batman: Arkham Knight', 'The Arkham trilogy ends with Gotham evacuated and the Batmobile deployed.', 'Scarecrow threatens Gotham with a fear toxin and the Arkham Knight leads an army against Batman. The Batmobile joins freeflow combat and predator rooms, and the city is larger than in previous games.', 'Rocksteady Studios', 'Warner Bros. Games', '2015-06-23', '["Action","Adventure"]', '["Superhero","Open World","Stealth","Action"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/batman-arkham-knight.hero.jpg', '/covers/batman-arkham-knight.box.jpg', 87, '$3.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player"]', 'M (Mature 17+)', 'Unreal Engine 3', 'Batman: Arkham', 87, 'Very Positive', NULL, 16, 40, '[]', '["The Batmobile is a core mechanic rather than a set piece.","The PC version was pulled from sale in 2015 while its port was fixed.","It was Rocksteady''s final game in the Arkham series."]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('91709a27-53e0-42e0-a3cd-bcec69d0610d', 'bioshock-infinite', 'BioShock Infinite', 'A floating city, a girl who can tear reality and a debt to collect.', 'Booker DeWitt is sent to Columbia to retrieve Elizabeth. The city is bright and crowded where Rapture was dark, and the story turns on choices, alternate versions of people and the ending.', 'Irrational Games', '2K', '2013-03-26', '["Shooter","Adventure"]', '["First-Person","Story Rich","Sci-Fi","Alternate History"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/bioshock-infinite.hero.jpg', '/covers/bioshock-infinite.box.jpg', 94, '$29.99', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player"]', 'M (Mature 17+)', 'Unreal Engine 3', 'BioShock', 94, 'Very Positive', NULL, 12, 25, '[]', '["Columbia floats above the United States in 1912 and is built on an alternate history.","Elizabeth can open tears that pull objects and scenery from other realities.","The Burial at Sea expansions connect the story back to Rapture."]'),
('bbf455f3-f72b-4829-9c94-32eefef345df', 'dishonored-2', 'Dishonored 2', 'Two assassins, one throne and a city of clockwork and dust.', 'Emily Kaldwin or Corvo Attano reclaim the throne from a usurper. Levels such as the Clockwork Mansion and A Crack in the Slab are built as large immersive-sim sandboxes.', 'Arkane Studios', 'Bethesda Softworks', '2016-11-11', '["Action","Adventure"]', '["Stealth","Immersive Sim","First-Person","Choices Matter"]', '["Single-player","Achievements","Cloud Saves"]', '/covers/dishonored-2.hero.jpg', '/covers/dishonored-2.box.jpg', 88, '$5.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player"]', 'M (Mature 17+)', 'Void Engine', 'Dishonored', 88, 'Very Positive', NULL, 12, 30, '[]', '["Emily and Corvo have different power sets and can be played separately.","The Clockwork Mansion rearranges its rooms while you are inside.","A Crack in the Slab lets you move between two versions of the same house."]'),
('2d07bb56-6832-4bea-94e3-1bb1295993f0', 'prey-2017', 'Prey', 'A space station overrun by shapeshifters and one very confused scientist.', 'Morgan Yu wakes on Talos I and finds the station''s experiments loose. Mimics hide as ordinary objects, and the immersive-sim design lets you approach almost every room from several directions.', 'Arkane Studios', 'Bethesda Softworks', '2017-05-05', '["Shooter","RPG"]', '["Sci-Fi","Immersive Sim","Horror","First-Person"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/prey-2017.hero.jpg', '/covers/prey-2017.box.jpg', 82, '$7.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player"]', 'M (Mature 17+)', 'CryEngine', 'Prey', 82, 'Very Positive', NULL, 16, 40, '[]', '["It shares a name with the 2006 Prey but is not a sequel or a remake.","Mimics can disguise themselves as cups, chairs and other props.","The GLOO cannon is used for both combat and climbing."]'),
('263912e8-7d60-4898-8760-e987128080f6', 'doom-2016', 'DOOM', 'A fast, brutal reboot that pushes you toward the fight.', 'The Doom Slayer wakes in a UAC facility on Mars and works his way back to Hell. Glory kills, no reloading and arenas that lock you in keep the pace high, with secrets hidden around every corner.', 'id Software', 'Bethesda Softworks', '2016-05-13', '["Shooter","Action"]', '["First-Person","Fast-Paced","Demons","Sci-Fi"]', '["Single-player","Achievements","Cloud Saves"]', '/covers/doom-2016.hero.jpg', '/covers/doom-2016.box.jpg', 85, '$3.99', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player","Multi-player"]', 'M (Mature 17+)', 'id Tech 6', 'DOOM', 85, 'Overwhelmingly Positive', NULL, 11, 25, '[]', '["Glory kills restore health, which encourages aggressive play.","The soundtrack by Mick Gordon blends industrial metal with the game''s audio.","It was the first main DOOM game since 2004''s DOOM 3."]'),
('0e67b3c4-217d-4a4a-8883-402d831afe78', 'titanfall-2', 'Titanfall 2', 'Pilot and Titan combat with one of the best shooter campaigns around.', 'Jack Cooper inherits the Titan BT-7274 and has to stop the IMC''s plan. Movement is wall-running and grappling, and the campaign builds levels around single mechanics before moving on.', 'Respawn Entertainment', 'Electronic Arts', '2016-10-28', '["Shooter","Action"]', '["First-Person","Sci-Fi","Mechs","Multiplayer"]', '["Single-player","Online PvP","Controller Support","Achievements"]', '/covers/titanfall-2.hero.jpg', '/covers/titanfall-2.box.jpg', 89, '$3.99', 0, '["PC","PlayStation 4","Xbox One"]', '["Single-player","Multi-player","Online PvP","PvP"]', 'M (Mature 17+)', 'Source Engine', 'Titanfall', 89, 'Overwhelmingly Positive', NULL, 6, 15, '[]', '["The Effect and Cause level lets players jump between two time periods at will.","Respawn was founded by developers who worked on Call of Duty: Modern Warfare.","It released between Battlefield 1 and Call of Duty: Infinite Warfare in 2016."]'),
('04028329-8e02-4523-b29d-d04677fb674e', 'control', 'Control', 'A paranormal agency headquarters that keeps rearranging itself.', 'Jesse Faden becomes Director of the Federal Bureau of Control and searches the Oldest House for her brother. Telekinesis, levitation and a transforming gun carry the combat.', 'Remedy Entertainment', '505 Games', '2019-08-27', '["Action","Adventure"]', '["Sci-Fi","Paranormal","Third-Person","Weird"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/control.hero.jpg', '/covers/control.box.jpg', 85, '$29.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S"]', '["Single-player"]', 'M (Mature 17+)', 'Northlight Engine', 'Control', 85, 'Very Positive', NULL, 12, 30, '[]', '["The Oldest House shifts its layout, so rooms move between visits.","The Ashtray Maze level is built around a song by the band The Old Gods of Asgard.","Remedy connected its story to Alan Wake through the AWE expansion."]'),
('983fda1a-38e0-4af2-95a8-95313ad2a3ba', 'outer-wilds', 'Outer Wilds', 'A solar system stuck in a 22-minute loop and a mystery to solve.', 'Every 22 minutes the sun goes supernova and you wake up at the campfire again. Progress comes from understanding the world rather than from upgrades, and the only tool is a signalscope, a probe and a ship.', 'Mobius Digital', 'Annapurna Interactive', '2019-05-28', '["Adventure","Simulation"]', '["Exploration","Time Loop","Space","Mystery"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/outer-wilds.hero.jpg', '/covers/outer-wilds.box.jpg', 85, '$12.49', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'E10+ (Everyone 10+)', 'Unity', 'N/A', 85, 'Overwhelmingly Positive', NULL, 16, 30, '[]', '["The game has no combat and no permanent upgrades.","Knowledge is the only thing carried between loops.","The Echoes of the Eye expansion added a hidden location to the solar system."]'),
('27ac2d18-f3c7-4375-a9a6-26bb3aa22621', 'disco-elysium', 'Disco Elysium', 'A detective story where your own skills argue with you.', 'A detective with no memory investigates a murder in Martinaise. There is no combat: skills like Logic, Empathy and Inland Empire talk to you, and dialogue checks shape the case and the character.', 'ZA/UM', 'ZA/UM', '2019-10-15', '["RPG","Adventure"]', '["Story Rich","Detective","Choices Matter","Isometric"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/disco-elysium.hero.jpg', '/covers/disco-elysium.box.jpg', 97, '$39.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', 'M (Mature 17+)', 'Unity', 'N/A', 97, 'Very Positive', NULL, 25, 60, '[]', '["The game has no combat encounters at all.","The Final Cut edition added full voice acting for every line.","Its writing team drew on the studio''s experience with tabletop role-playing."]'),
('17f71a7c-4e66-48ec-aa11-9abd3ccf38c0', 'celeste', 'Celeste', 'A precise platformer about climbing a mountain and anxiety.', 'Madeline climbs Celeste Mountain one screen at a time. The dash, the air control and the level design are exact, and the story treats the climb as a way through panic rather than around it.', 'Maddy Makes Games', 'Maddy Makes Games', '2018-01-25', '["Platformer","Adventure"]', '["Platformer","Difficult","Pixel Art","Story Rich"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/celeste.hero.jpg', '/covers/celeste.box.jpg', 88, '$4.99', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player"]', 'E10+ (Everyone 10+)', 'In-house (Maddy Makes Games)', 'N/A', 88, 'Very Positive', NULL, 8, 25, '[]', '["It started as a small prototype made for a game jam.","An assist mode lets players slow the game down or skip chapters.","The soundtrack was composed by Lena Raine."]'),
('021a1cec-68e0-4641-aee3-3299e8ad4333', 'vampire-survivors', 'Vampire Survivors', 'Survive waves of monsters with a weapon that fires itself.', 'You only control movement; the weapons fire on their own. Runs last up to 30 minutes, and each level-up adds or upgrades a weapon in a build that either snowballs or collapses.', 'poncle', 'poncle', '2022-10-20', '["Action","RPG"]', '["Roguelike","Bullet Heaven","Pixel Art","Cheap"]', '["Single-player","Online Co-op","Controller Support","Achievements","Cloud Saves","Remote Play"]', '/covers/vampire-survivors.hero.jpg', '/covers/vampire-survivors.box.jpg', 87, '$4.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player","Multi-player","Online Co-op"]', NULL, 'Phaser', 'N/A', 87, 'Overwhelmingly Positive', NULL, 6, 40, '[]', '["It was created largely by a single developer, poncle.","The game popularised the ''bullet heaven'' genre of auto-attacking survival games.","It began as a small browser game before coming to Steam."]');
INSERT INTO games (id, slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured, platforms_released, game_modes, esrb_rating, engine, series, metacritic_score, steam_reviews_label, player_count, main_story_hours, completionist_hours, awards, trivia) VALUES
('ca8aa153-d9c1-4cde-8ee8-da1c8b0d90eb', 'factorio', 'Factorio', 'Build a factory on an alien planet, then make it bigger.', 'Crash-landed engineers mine, smelt and assemble their way to a rocket. Belts, inserters and trains turn into a logistics puzzle, and the native biters react to the pollution the factory produces.', 'Wube Software', 'Wube Software', '2020-08-14', '["Simulation","Strategy"]', '["Automation","Base Building","Sandbox","Optimization"]', '["Single-player","Online Co-op","Achievements","Cloud Saves"]', '/covers/factorio.hero.jpg', '/covers/factorio.box.jpg', 90, '$35.00', 0, '["PC","Nintendo Switch"]', '["Single-player","Multi-player","Online Co-op"]', NULL, 'In-house (Wube Software)', 'N/A', 90, 'Overwhelmingly Positive', NULL, 60, 300, '[]', '["The game deliberately never goes on sale.","It spent years in early access before the 1.0 release in 2020.","The Space Age expansion added other planets and space platforms in 2024."]'),
('466b4063-d092-4f25-bc20-12ab8a132dcd', 'balatro', 'Balatro', 'Poker hands turned into a roguelike deckbuilder about multipliers.', 'You play poker hands to score chips, and Joker cards bend the rules until a pair beats a royal flush. Each run adds new cards, and the score requirements climb faster than any honest deck can keep up with.', 'LocalThunk', 'Playstack', '2024-02-20', '["Strategy","RPG"]', '["Roguelike","Deckbuilder","Card Game","Addictive"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/balatro.hero.jpg', '/covers/balatro.box.jpg', 90, '$14.99', 0, '["PC","PlayStation 4/5","Xbox One/Series X|S","Nintendo Switch"]', '["Single-player"]', NULL, 'LÖVE', 'N/A', 90, 'Overwhelmingly Positive', NULL, 20, 80, '[]', '["It was made by a solo developer under the name LocalThunk.","Joker cards provide most of the game''s rule-breaking synergies.","It was one of the surprise hits of 2024 and sold millions of copies."]'),
('4ce75835-8e57-4186-8d8f-543b9775946b', 'cuphead', 'Cuphead', 'A run-and-gun boss rush drawn like a 1930s cartoon.', 'Cuphead and Mugman owe the devil and have to collect souls from bosses. Every fight is a pattern to learn, and the animation is hand-drawn with watercolour backgrounds.', 'Studio MDHR', 'Studio MDHR', '2017-09-29', '["Platformer","Action"]', '["Difficult","Boss Rush","Hand-Drawn","Run and Gun"]', '["Single-player","Local Co-op","Controller Support","Achievements","Cloud Saves","Remote Play"]', '/covers/cuphead.hero.jpg', '/covers/cuphead.box.jpg', 88, '$13.99', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player","Multi-player","Local Co-op"]', 'E10+ (Everyone 10+)', 'Unity', 'N/A', 88, 'Very Positive', NULL, 10, 25, '[]', '["Every frame of animation was drawn by hand in a 1930s style.","The Delicious Last Course expansion added a new island and playable character.","The game was announced in 2014 and delayed several times before release."]'),
('87c927dd-9b6e-4bf8-a9f0-8bc2fd4a3c01', 'dead-cells', 'Dead Cells', 'A roguelite metroidvania with fast combat and permanent unlocks.', 'A headless prisoner fights through a shifting island, dying and returning with new weapons unlocked. Combat is quick and readable, and the difficulty climbs with each Boss Cell.', 'Motion Twin', 'Motion Twin', '2018-08-07', '["Action","Platformer"]', '["Roguelite","Metroidvania","Pixel Art","Difficult"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/dead-cells.hero.jpg', '/covers/dead-cells.box.jpg', 89, '$9.99', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player"]', 'T (Teen)', 'In-house (Motion Twin)', 'N/A', 89, 'Overwhelmingly Positive', NULL, 15, 60, '[]', '["Motion Twin is a worker cooperative, and the game was its last project before the team split off Evil Empire.","Boss Cells are optional difficulty levels unlocked by beating the game.","Free updates added crossover content with other indie games."]'),
('246866bc-2bbd-4257-be63-6b7e4e113e17', 'slay-the-spire', 'Slay the Spire', 'A deckbuilder where every card choice changes the climb.', 'Build a deck from card rewards and relics while climbing a spire of increasingly nasty encounters. Four characters play differently, and the map shows what is coming so routes can be planned.', 'Mega Crit', 'Mega Crit', '2019-01-23', '["Strategy","RPG"]', '["Deckbuilder","Roguelike","Turn-Based","Strategy"]', '["Single-player","Controller Support","Achievements","Cloud Saves"]', '/covers/slay-the-spire.hero.jpg', '/covers/slay-the-spire.box.jpg', 89, '$6.24', 0, '["PC","PlayStation 4","Xbox One","Nintendo Switch"]', '["Single-player"]', 'E10+ (Everyone 10+)', 'Unity', 'N/A', 89, 'Very Positive', NULL, 20, 80, '[]', '["It was developed by a two-person team at Mega Crit.","The map is visible in advance, so route planning is part of the strategy.","It is often credited with popularising the modern deckbuilder roguelike."]');
